#include <fcntl.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define GPIO_BASE "/dev/gpiochip0"
#define GPIO_2 (2 + 32)
#define GPIO_3 (3 + 32)

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request_2, *request_3;
    int ret;

    chip = gpiod_chip_open(GPIO_BASE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    request_2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!request_2) {
        perror("Failed to get GPIO line 2");
        gpiod_chip_close(chip);
        return 1;
    }

    request_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!request_3) {
        perror("Failed to get GPIO line 3");
        gpiod_line_request_free(request_2);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_direction_output(request_2, 0);
    gpiod_line_request_direction_output(request_3, 0);

    while (1) {
        gpiod_line_set_value(request_2, 1);
        gpiod_line_set_value(request_3, 0);
        sleep(1);

        gpiod_line_set_value(request_2, 0);
        gpiod_line_set_value(request_3, 1);
        sleep(1);
    }

    gpiod_line_request_free(request_2);
    gpiod_line_request_free(request_3);
    gpiod_chip_close(chip);

    return 0;
}

