#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <gpiod.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_REG_COUNTH 0x07
#define MLX90614_REG_COUNTL 0x08
#define MLX90614_REG_TEMP_MSB 0x09
#define MLX90614_REG_TEMP_LSB 0x0A
#define MLX90614_REG_PON 0x0C

static int mlx_i2c_file;
static gpio_chan_t *gpio_reset;

int init_i2c() {
    if ((mlx_i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        return -1;
    }

    if (ioctl(mlx_i2c_file, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(mlx_i2c_file);
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    gpio_reset = gpiod_chip_get_line(chip, 18);
    if (!gpio_reset) {
        perror("Failed to get gpio line 18");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_reset, "mlx_reset", GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request gpio line 18");
        gpiod_line_release(gpio_reset);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(gpio_reset, 1);
    usleep(100000);
    gpiod_line_set_value(gpio_reset, 0);
    usleep(100000);
    gpiod_line_set_value(gpio_reset, 1);

    return 0;
}

uint16_t read_temp() {
    uint16_t count, temp_msb, temp_lsb;

    if (write_reg16(MLX90614_REG_COUNTH, 0x00) < 0)
        return 0;
    if (write_reg16(MLX90614_REG_COUNTL, 0x00) < 0)
        return 0;
    if (write_reg8(MLX90614_REG_PON, 0x03) < 0)
        return 0;

    usleep(250000);

    if (read_reg16(MLX90614_REG_TEMP_MSB, &temp_msb) < 0)
        return 0;
    if (read_reg16(MLX90614_REG_TEMP_LSB, &temp_lsb) < 0)
        return 0;

    return (temp_msb << 8) | temp_lsb;
}

int write_reg8(uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    return write(mlx_i2c_file, data, 2);
}

int write_reg16(uint8_t reg, uint16_t value) {
    uint8_t data[3] = {reg, value >> 8, value & 0xFF};
    return write(mlx_i2c_file, data, 3);
}

int read_reg16(uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    ssize_t bytes_read;

    if ((bytes_read = read(mlx_i2c_file, data, 2)) != 2) {
        perror("Failed to read from i2c device");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

void cleanup() {
    if (gpio_reset) {
        gpiod_line_release(gpio_reset);
        gpiod_line_free(gpio_reset);
    }

    if (mlx_i2c_file >= 0) {
        if (ioctl(mlx_i2c_file, I2C_SLAVE, 0x00) < 0)
            perror("Failed to release bus access");
        close(mlx_i2c_file);
    }
}

int main() {
    int ret;

    if (init_gpio() < 0)
        return 1;

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        uint16_t temp = read_temp();
        if (temp == 0) {
            perror("Failed to read temperature");
            break;
        }

        printf("Temperature: %.2f°C\n", (float)temp / 16.0);
        sleep(5);
    }

    cleanup();
    return temp == 0 ? 1 : 0;
}

