#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 50
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MIN 0
#define DELAY_MS 500

int main() {
    int ret;
    uint32_t duty_cycle;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioTermIO() < 0) {
        fprintf(stderr, "Failed to take terminal I/O control\n");
        goto cleanup;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_PIN);
        goto cleanup;
    }

    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", GPIO_PIN);
        goto cleanup;
    }

    for (duty_cycle = PWM_DUTY_MIN; duty_cycle <= PWM_DUTY_MAX; duty_cycle += 5) {
        gpioPWM(GPIO_PIN, duty_cycle);
        printf("Duty cycle: %d%%\n", duty_cycle);
        sleep(DELAY_MS / 1000.0);
    }

cleanup:
    gpioTermPWM(GPIO_PIN);
    gpioTermIO();
    gpioTerm();

    return (gpioLastError() != 0) ? 1 : 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 27
#define MAX_DISTANCE 250
#define MIN_DISTANCE 2
#define TIMEOUT_US 100000

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int ret;

    if (!(chip = gpiod_chip_open_byname("gpiochip0"))) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (!trig) {
        perror("Failed to get TRIG line");
        gpiod_chip_put(chip);
        return 1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("Failed to get ECHO line");
        gpiod_line_put(trig);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_request_output(echo, GPIOD_LINE_ACTIVE_LOW);
    gpiod_line_set_value(echo, 0);

    while (1) {
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        ret = gpiod_line_read_value_with_timeout(echo, TIMEOUT_US);
        if (ret < 0) {
            perror("Failed to read ECHO line");
            break;
        }

        usleep(58 * 1000); // Wait for 58 microseconds more than the time for the echo to return

        ret = gpiod_line_read_value_with_timeout(echo, TIMEOUT_US);
        if (ret < 0) {
            perror("Failed to read ECHO line");
            break;
        }

        if (ret == 1) {
            continue;
        }

        long duration = (usleep_time() - gpiod_line_get_last_value_time(echo)) * 1000;
        double distance = (duration * 0.0343) / 2;

        if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
            printf("Invalid distance value: %.2f cm\n", distance);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_put(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADS1115_ADDR 0x28
#define ADS1115_REG_POINTER 0x40
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_RESULT 0x02
#define ADS1115_REG_MUX_SINGLE_END 0x40
#define ADS1115_REG_PGA_2_048V 0x00
#define ADS1115_REG_MODE_SINGLE_SHOT_1_SHOT 0x80
#define ADS1115_REG_MODE_CONTINUOUS_CONVERSION 0x00
#define ADS1115_REG_DATA_RATE_8SPS 0x07
#define ADS1115_REG_RESOLUTION_12BIT 0x03
#define ADS1115_REG_COMP_QUEUE_DISABLE 0x00
#define ADS1115_REG_COMP_QUEUE_ENABLE 0x01
#define ADS1115_REG_COMP_WINDOW_VALUE 0x00
#define ADS1115_REG_COMP_WINDOW_WIDTH 0x00
#define ADS1115_REG_COMP_LATCH_OFF 0x00
#define ADS1115_REG_COMP_LATCH_ON 0x01
#define ADS1115_REG_COMP_INVERTED 0x00
#define ADS1115_REG_COMP_NON_INVERTED 0x01
#define ADS1115_REG_COMP_QUEUE_EMPTY 0x00
#define ADS1115_REG_COMP_QUEUE_FULL 0x01
#define ADS1115_REG_COMP_QUEUE_OVERFLOW 0x02
#define ADS1115_REG_COMP_QUEUE_UNDERFLOW 0x03
#define ADS1115_REG_COMP_QUEUE_ACTIVE 0x04

#define GPIO_LINE_ADC_CS 21

int main() {
    int i2c_fd, gpio_fd;
    int ret;
    unsigned char config_reg;
    unsigned short data;
    struct gpiod_line_request line_req;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO line for ADC CS
    if ((gpio_fd = gpiod_open_name_with_label("gpiochip0", "gpio-21")) < 0) {
        perror("Failed to open GPIO line for ADC CS");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO line for ADC CS as output
    if (gpiod_line_request_dtbo(gpio_fd, &line_req, "adc-cs") < 0) {
        perror("Failed to request GPIO line for ADC CS");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    gpiod_line_set_value(gpio_fd, line_req.gpio, 1);

    // Configure ADS1115
    config_reg = ADS1115_REG_MUX_SINGLE_END | ADS1115_REG_PGA_2_048V | ADS1115_REG_MODE_SINGLE_SHOT_1_SHOT | ADS1115_REG_DATA_RATE_8SPS | ADS1115_REG_RESOLUTION_12BIT | ADS1115_REG_COMP_QUEUE_DISABLE;
    ret = write(i2c_fd, &config_reg, 1);
    if (ret != 1) {
        perror("Failed to write configuration register");
        gpiod_line_release(gpio_fd, line_req);
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    while (1) {
        // Start conversion
        config_reg = ADS1115_REG_CONVERT | ADS1115_REG_POINTER;
        ret = write(i2c_fd, &config_reg, 1);
        if (ret != 1) {
            perror("Failed to start conversion");
            gpiod_line_release(gpio_fd, line_req);
            close(i2c_fd);
            close(gpio_fd);
            return 1;
        }

        // Wait for conversion to complete
        usleep(100000);

        // Read result
        ret = read(i2c_fd, &data, 2);
        if (ret != 2) {
            perror("Failed to read result");
            gpiod_line_release(gpio_fd, line_req);
            close(i2c_fd);
            close(gpio_fd);
            return 1;
        }

        // Check for valid reading
        if ((data & 0x00ff) > 4095 || (data & 0xff00) != 0) {
            printf("Invalid reading\n");
            continue;
        }

        // Print reading
        printf("Reading: %d\n", data & 0x00ff);

        // Wait 5 seconds
        sleep(5);
    }

    // Release GPIO line for ADC CS
    gpiod_line_release(gpio_fd, line_req);

    // Close I2C bus
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

