        perror("Failed to find GPIO 18");
        gpiod_line_request_free(request_17);
        gpiod_chip_close(chip);
        return 1;
    }

    gpio_17 = gpiod_line_get_number(request_17);
    gpio_18 = gpiod_line_get_number(request_18);

    gpiod_line_request_direction_output(request_17, 1);
    gpiod_line_request_direction_output(request_18, 1);

    while (1) {
        gpiod_line_set_value(request_17, 1);
        gpiod_line_set_value(request_18, 0);
        printf("GPIO 17: ON, GPIO 18: OFF\n");
        usleep(100000);

        gpiod_line_set_value(request_17, 0);
        gpiod_line_set_value(request_18, 1);
        printf("GPIO 17: OFF, GPIO 18: ON\n");
        usleep(100000);
    }

    gpiod_line_request_free(request_17);
    gpiod_line_request_free(request_18);
    gpiod_chip_close(chip);

    return 0;
}

