    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_state state;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    request = gpiod_chip_get_line_request(chip, 2);
    if (!request) {
        perror("Failed to get line request for GPIO 2");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable line request for GPIO 2");
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        ret = gpiod_line_get_value(request, &state);
        if (ret < 0) {
            perror("Failed to get line value for GPIO 2");
