        if (ret < 0) {
            perror("Failed to set line value for GPIO 2");
            continue;
        }

        sleep(1);
    }

    ret = gpiod_line_request_disable(request);
    if (ret < 0) {
        perror("Failed to disable line request for GPIO 2");
    }

