#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio/consumer.h>

#define TRIG_GPIO 18
#define ECHO_GPIO 17
#define MAX_DISTANCE 250
#define MIN_DISTANCE 2

int main() {
    int ret;
    int trig_fd, echo_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    unsigned int trig_value = GPIOD_VALUE_HIGH;
    unsigned int echo_value = GPIOD_VALUE_LOW;
    unsigned int echo_last_value = GPIOD_VALUE_HIGH;
    unsigned long long start_time, end_time, time_diff;
    float distance;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (!trig_line) {
        perror("Failed to get line for TRIG_GPIO");
        gpiod_chip_put(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("Failed to get line for ECHO_GPIO");
        gpiod_line_put(trig_line);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_request_line(echo_line, "ultrasonic_echo", GPIOD_LINE_REQUEST_INPUT);
    gpiod_line_request_line(trig_line, "ultrasonic_trig", GPIOD_LINE_REQUEST_OUTPUT);

    trig_fd = gpiod_line_get_fd(trig_line);
    echo_fd = gpiod_line_get_fd(echo_line);

    while (1) {
        gpiod_line_set_value(trig_line, trig_value);
        usleep(100000); // Delay for 100ms to ensure the signal is stable
        gpiod_line_set_value(trig_line, echo_value);

        echo_last_value = echo_value;
        ret = read(echo_fd, &echo_value, sizeof(echo_value));
        if (ret < 0) {
            perror("Failed to read from ECHO_GPIO");
            break;
        }

        start_time = get_monotonic_ns();
        while (echo_value == echo_last_value) {
            usleep(10000); // Poll every 10ms
            ret = read(echo_fd, &echo_value, sizeof(echo_value));
            if (ret < 0) {
                perror("Failed to read from ECHO_GPIO");
                break;
            }
        }
        end_time = get_monotonic_ns();

        time_diff = end_time - start_time;
        distance = time_diff * (343 / 2) / 1e9;

        if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
            printf("Error: Distance out of range [%f]\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        usleep(1000000); // Delay for 1 second
    }

    gpiod_line_set_value(trig_line, echo_value);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_put(chip);

    return 0;
}

