        // Request lines
        req[i] = gpiod_chip_request_line(chip, i, GPIO_REQUEST_FLAGS);
        if (!req[i]) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            close(gpio_fd[i]);
