    gpiod_line_request_line(gpiochip_get_byname("gpiochip0"), DHT11_DATA_PIN, "dht11_data", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING);

    for (i = 0; i < 5; i++) {
        gpiod_line_get_value(gpio_data_lines[DHT11_DATA_PIN]) ? received[i] = start_sequence[i] : received[i] = received[i] ^ 0x01;
        gpiod_line_set_value(gpio_data_lines[DHT11_DATA_PIN], received[i] & 0x01);
        usleep(48);
    }

    gpiod_line_set_value(gpio_data_lines[DHT11_DATA_PIN], 0);
    usleep(76);

    for (i = 0; i < 40; i++) {
        uint8_t bit = gpiod_line_get_value(gpio_data_lines[DHT11_DATA_PIN]) ? 1 : 0;
        gpiod_line_set_value(gpio_data_lines[DHT11_DATA_PIN], 0);
        usleep(16);
        gpiod_line_set_value(gpio_data_lines[DHT11_DATA_PIN], 1);
        usleep(16);

        if (bit != data[i + 4]) {
            gpiod_line_release_line(gpio_data_lines[DHT11_DATA_PIN]);
            return 1;
        }
    }

    gpiod_line_release_line(gpio_data_lines[DHT11_DATA_PIN]);

    for (i = 0; i < 4; i++) {
        data[i] = received[i + 4];
    }

    data[4] = checksum ^ received[4] ^ received[5] ^ received[4 + data[4]];

    if (data[4] != received[4 + data[4]]) {
        return 1;
    }

    return 0;
}

