        gpiod_line_put(line_23);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set direction as output
    ret = gpiod_line_request_output(line_23, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
