        gpiod_line_put(line_24);
        gpiod_line_put(line_23);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_24, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request output for GPIO_24");
        gpiod_line_put(line_23);
        gpiod_line_put(line_24);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set initial state
    ret = gpiod_line_set_value(line_23, 1);
    if (ret < 0) {
        perror("Failed to set initial state for GPIO_23");
        gpiod_line_put(line_24);
        gpiod_line_put(line_23);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line_24, 1);
    if (ret < 0) {
