    tcsetattr(uart_fd, TCSANOW, &options);

    // Main loop
    while (1) {
        if (gpiod_get_value(gpio_fd, 0)) {
            ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) {
