#define GPIO_11 17
#define GPIO_12 18
#define GPIO_17 11
#define GPIO_18 12

static int gpiod_fd;

static void gpiod_release(void) {
    if (gpiod_fd >= 0) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }
}

static int gpiod_init(void) {
    const char *const bus_names[] = { "gpiochip0", NULL };
    struct gpiod_chip *chip;
    int ret;

    gpiod_fd = gpiod_open_names_with_label(bus_names, "allwinner,sunxi-gpios", 0);
    if (gpiod_fd < 0) {
        perror("gpiod_open_names_with_label");
        return -1;
    }

    chip = gpiod_chip_get_by_index(gpiod_fd, 0);
    if (!chip) {
        perror("gpiod_chip_get_by_index");
        return -1;
    }

    return 0;
}

static int gpiod_setup(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_request_output(line, value);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }

    return 0;
}

static int gpiod_get_value(struct gpiod_line *line) {
    int ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }

    return ret;
}

int main(void) {
    struct gpiod_line *lines[4] = { NULL };
    int i;

    if (gpiod_init() < 0) {
        gpiod_release();
        return 1;
    }

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(gpiod_fd, GPIO_11 + i);
        if (!lines[i]) {
            perror("gpiod_chip_get_line");
            gpiod_release();
            return 1;
        }
    }

    for (i = 0; i < 4; i++) {
        if (gpiod_setup(lines[i], 0) < 0) {
            gpiod_release();
            return 1;
        }
        usleep(100000);
        if (gpiod_get_value(lines[i]) < 0) {
            gpiod_release();
            return 1;
        }
        printf("Initial state of GPIO%d: %s\n", GPIO_11 + i,
               gpiod_get_value(lines[i]) ? "High" : "Low");
    }

    for (;;) {
        for (i = 0; i < 4; i++) {
            if (gpiod_get_value(lines[i]) < 0) {
                gpiod_release();
                return 1;
            }
            if (gpiod_get_value(lines[i])) {
                if (gpiod_setup(lines[i], 0) < 0) {
                    gpiod_release();
                    return 1;
                }
            } else {
                if (gpiod_setup(lines[i], 1) < 0) {
                    gpiod_release();
                    return 1;
                }
            }
            usleep(100000);
        }
    }

    gpiod_release();
    return 0;
}

