#define ADXL345_ADDR 0x53
#define XOUT_H 0x32
#define XOUT_L 0x33
#define YOUT_H 0x34
#define YOUT_L 0x35
#define ZOUT_H 0x36
#define ZOUT_L 0x37

static int i2c_file;
static struct gpiod_chip *gpiochip;
static gpiod_line_request_data lines[1];

int init_i2c() {
    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        close(i2c_file);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (gpiochip) gpiod_chip_put(gpiochip);
    if (i2c_file >= 0) close(i2c_file);
}

int read_adxl345() {
    int x, y, z;
    uint8_t x_data[2], y_data[2], z_data[2];

    if (read(i2c_file, x_data, 2) != 2) {
        perror("Failed to read X data");
        return -1;
    }
    x = (x_data[0] << 8) | x_data[1];

    if (read(i2c_file, y_data, 2) != 2) {
        perror("Failed to read Y data");
        return -1;
    }
    y = (y_data[0] << 8) | y_data[1];

    if (read(i2c_file, z_data, 2) != 2) {
        perror("Failed to read Z data");
        return -1;
    }
    z = (z_data[0] << 8) | z_data[1];

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
    return 0;
}

int main() {
    int ret;

    if ((ret = init_i2c()) != 0) return ret;

    gpiod_chip_open_byname("gpiochip0", &gpiochip);
    lines[0].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    lines[0].consumer = "adxl345_reader";
    if (gpiod_chip_claim_line(gpiochip, 17, lines) < 0) {
        perror("Failed to claim GPIO line");
        goto cleanup;
    }

    struct timespec ts = { .tv_sec = 0, .tv_nsec = 100 * 1e6 };
    while (1) {
        nanosleep(&ts, NULL);
        if ((ret = read_adxl345()) != 0) break;
    }

cleanup:
    gpiod_line_release(gpiochip, lines[0].number);
    gpiod_chip_put(gpiochip);

    return 0;
}

