#define DHT22_RESET_PIN 23
#define DHT22_BUS_PIN 24

#define DHT22_READ_DELAY_US 80
#define DHT22_BIT_HIGH 1
#define DHT22_BIT_LOW 0

static int dht22_read(gpiod_line_request_ptr line_req) {
    int data = 0;
    int i;

    gpiod_line_set_value(line_req, DHT22_BIT_HIGH);
    usleep(DHT22_READ_DELAY_US);

    gpiod_line_set_value(line_req, DHT22_BIT_LOW);
    for (i = 0; i < 24; i++) {
        usleep(DHT22_READ_DELAY_US);
        data <<= 1;
        if (gpiod_line_get_value(line_req)) {
            data |= DHT22_BIT_HIGH;
        } else {
            data |= DHT22_BIT_LOW;
        }
    }

    return data;
}

static void dht22_reset(gpiod_line_request_ptr reset_req) {
    gpiod_line_set_value(reset_req, DHT22_BIT_LOW);
    usleep(18);
    gpiod_line_set_value(reset_req, DHT22_BIT_HIGH);
    usleep(40);
}

int main() {
    int ret;
    gpiod_line_request_ptr data_req, clock_req, reset_req, bus_req;
    gpiod_line_state_callback_t callback;
    struct gpiod_line_request data_req_data = {0};
    struct gpiod_line_request clock_req_data = {0};
    struct gpiod_line_request reset_req_data = {0};
    struct gpiod_line_request bus_req_data = {0};

    if ((ret = gpiod_claim_lines(&data_req_data, 1, "dht22_data", DHT22_DATA_PIN)) < 0) {
        perror("Failed to claim DHT22 data line");
        return 1;
    }
    data_req = gpiod_get_request(data_req_data);

    if ((ret = gpiod_claim_lines(&clock_req_data, 1, "dht22_clock", DHT22_CLOCK_PIN)) < 0) {
        perror("Failed to claim DHT22 clock line");
        gpiod_release_request(data_req);
        return 1;
    }
    clock_req = gpiod_get_request(clock_req_data);

    if ((ret = gpiod_claim_lines(&reset_req_data, 1, "dht22_reset", DHT22_RESET_PIN)) < 0) {
        perror("Failed to claim DHT22 reset line");
        gpiod_release_request(data_req);
        gpiod_release_request(clock_req);
        return 1;
    }
    reset_req = gpiod_get_request(reset_req_data);

    if ((ret = gpiod_claim_lines(&bus_req_data, 1, "dht22_bus", DHT22_BUS_PIN)) < 0) {
        perror("Failed to claim DHT22 bus line");
        gpiod_release_request(data_req);
        gpiod_release_request(clock_req);
        gpiod_release_request(reset_req);
        return 1;
    }
    bus_req = gpiod_get_request(bus_req_data);

    callback = [](struct gpiod_chan *chan, int event, void *user_data) {
        if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
            int data = dht22_read(data_req);
            if (data == 0x22) {
                int humidity = (data & 0x7f) * 10;
                int temperature = (data >> 8) * 256;
                temperature |= (dht22_read(data_req) << 8);
                temperature /= 10;
                printf("Humidity: %d%%, Temperature: %d°C\n", humidity, temperature);
            }
        }
    };

    gpiod_line_request_set_callback(data_req, callback, NULL);

    while (1) {
        dht22_reset(reset_req);
        usleep(200000);
    }

    gpiod_release_request(data_req);
    gpiod_release_request(clock_req);
    gpiod_release_request(reset_req);
    gpiod_release_request(bus_req);

