#define TCS34725_ADDR 0x29
#define TCS34725_ID 0x85
#define TCS34725_EN 18

int main() {
    int file;
    int ret;
    char buf[2];
    unsigned short id;
    unsigned short data[4];
    struct gpiod_line_request line_req;
    struct gpiod_line *line;

    // Open I2C bus
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    // Initialize I2C slave address
    if (ioctl(file, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(file);
        return 1;
    }

    // Check if TCS34725 is present
    if (read(file, buf, 1) != 1) {
        perror("Failed to read from TCS34725");
        close(file);
        return 1;
    }

    if (buf[0] != TCS34725_ID) {
        perror("TCS34725 not found");
        close(file);
        return 1;
    }

    // Request GPIO line for enabling the sensor
    line = gpiod_chip_get_line(gpiod_chip_get_byname("gpiochip0"), TCS34725_EN);
    if (IS_ERR(line)) {
        perror("Failed to get GPIO line");
        close(file);
        return 1;
    }

    gpiod_line_request_dt(&line_req, line, GPIOD_LINE_REQUEST_DIRECTION_OUT, "tcs34725_en");
    ret = gpiod_line_request_enable(line, &line_req);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        close(file);
        return 1;
    }

    gpiod_line_set_value(line, 1);

    // Main loop
    while (1) {
        // Read data from TCS34725
        ret = i2c_smbus_read_word_data(file, 0x00);
        if (ret < 0) {
            perror("Failed to read data from TCS34725");
            break;
        }

        data[0] = (ret & 0xFF) << 8 | (ret >> 8);
        ret = i2c_smbus_read_word_data(file, 0x02);
        if (ret < 0) {
            perror("Failed to read data from TCS34725");
            break;
        }

        data[1] = (ret & 0xFF) << 8 | (ret >> 8);
        ret = i2c_smbus_read_word_data(file, 0x04);
        if (ret < 0) {
            perror("Failed to read data from TCS34725");
            break;
        }

        data[2] = (ret & 0xFF) << 8 | (ret >> 8);
        ret = i2c_smbus_read_word_data(file, 0x06);
        if (ret < 0) {
            perror("Failed to read data from TCS34725");
            break;
        }

        data[3] = (ret & 0xFF) << 8 | (ret >> 8);

        printf("R, G, B, C: %d, %d, %d, %d\n", data[0], data[1], data[2], data[3]);

        usleep(200000); // Wait 0.2 seconds
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close I2C bus
    close(file);

    return 0;
}

