static void gpiod_line_request_func(struct gpiod_line_request *request, int event, void *user_data) {
    (void)request;
    (void)user_data;

    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        printf("GPIO %d state changed to LOW\n", request->number);
    } else if (event == GPIOD_LINE_EVENT_EDGE_RISING) {
        printf("GPIO %d state changed to HIGH\n", request->number);
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request[3];

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    for (int i = GPIO_18; i <= GPIO_22; ++i) {
        struct gpiod_line_request_config config = {
            .direction = GPIOD_IN,
            .edge_debounce = 10,
            .event_types = GPIOD_LINE_EVENT_EDGE_FALLING | GPIOD_LINE_EVENT_EDGE_RISING,
            .callback = gpiod_line_request_func,
            .consumer_data = &i,
        };

        request[i - GPIO_18] = gpiod_line_request_get(chip, i);
        if (!request[i - GPIO_18]) {
            perror("Failed to get line request for GPIO");
            goto cleanup;
        }

        ret = gpiod_line_request_configure_async(request[i - GPIO_18], &config);
        if (ret < 0) {
            perror("Failed to configure line request for GPIO");
            goto cleanup;
        }
    }

    for (int i = GPIO_18; i <= GPIO_22; ++i) {
        ret = gpiod_line_request_configure_sync(request[i - GPIO_18], &config);
        if (ret < 0) {
            perror("Failed to synchronize line request for GPIO");
            goto cleanup;
        }
    }

    // Set GPIO 18, GPIO 21, and GPIO 22 to output
    struct gpiod_line_request_config output_config = {
        .direction = GPIOD_OUT,
        .consumer_data = NULL,
    };

    ret = gpiod_line_request_configure_async(request[GPIO_18 - GPIO_18], &output_config);
    if (ret < 0) {
        perror("Failed to configure output for GPIO 18");
        goto cleanup;
    }

    ret = gpiod_line_request_configure_sync(request[GPIO_18 - GPIO_18], &output_config);
    if (ret < 0) {
        perror("Failed to synchronize output for GPIO 18");
        goto cleanup;
    }

    ret = gpiod_line_set_value(request[GPIO_18 - GPIO_18], 1);
    if (ret < 0) {
        perror("Failed to set GPIO 18 to HIGH");
        goto cleanup;
    }

    ret = gpiod_line_request_configure_async(request[GPIO_21 - GPIO_18], &output_config);
    if (ret < 0) {
        perror("Failed to configure output for GPIO 21");
        goto cleanup;
    }

    ret = gpiod_line_request_configure_sync(request[GPIO_21 - GPIO_18], &output_config);
    if (ret < 0) {
        perror("Failed to synchronize output for GPIO 21");
        goto cleanup;
    }

    ret = gpiod_line_set_value(request[GPIO_21 - GPIO_18], 1);
    if (ret < 0) {
        perror("Failed to set GPIO 21 to HIGH");
        goto cleanup;
    }

    ret = gpiod_line_request_configure_async(request[GPIO_22 - GPIO_18], &output_config);
    if (ret < 0) {
        perror("Failed to configure output for GPIO 22");
        goto cleanup;
    }

    ret = gpiod_line_request_configure_sync(request[GPIO_22 - GPIO_18], &output_config);
    if (ret < 0) {
        perror("Failed to synchronize output for GPIO 22");
        goto cleanup;
    }

    ret = gpiod_line_set_value(request[GPIO_22 - GPIO_18], 0);
    if (ret < 0) {
        perror("Failed to set GPIO 22 to LOW");
        goto cleanup;
    }

    sleep(5);

    ret = gpiod_line_set_value(request[GPIO_22 - GPIO_18], 1);
    if (ret < 0) {
        perror("Failed to set GPIO 22 to HIGH");
        goto cleanup;
    }

cleanup:
    for (int i = GPIO_18; i <= GPIO_22; ++i) {
        gpiod_line_request_put(request[i - GPIO_18]);
    }

    gpiod_chip_put(chip);

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/ioctl.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>

#define PI_CAMERA_BUS_INFO "picamera"
#define PI_CAMERA_DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buf_ptr;
    ssize_t bytes_read;
    int ret;

    fd = open(PI_CAMERA_DEVICE_NAME, O_RDWR | O_NONBLOCK | O_EXCL);

    if (fd < 0) {
        perror("Error opening camera device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        close(fd);
        return 1;
    }

    if (strcmp(cap.driver, "v4l2-subdev") != 0) {
        fprintf(stderr, "Driver does not support V4L2 subdev API\n");
        close(fd);
        return 1;
    }

    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix_fmt = V4L2_PIX_FMT_JPEG;
    fmt.fmt.field = V4L2_FIELD_ANY;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &fmt.type) < 0) {
        perror("Error starting stream");
        close(fd);
        return 1;
    }

    buf = req.buffers[0];
    buf_ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

    if (buf_ptr == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    usleep(100000); // Wait for the buffer to be filled

    bytes_read = read(fd, buf_ptr, buf.length);

    if (bytes_read < 0) {
        perror("Error reading buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    FILE *image_file = fopen("image.jpg", "wb");
    fwrite(buf_ptr, bytes_read, 1, image_file);
    fclose(image_file);

    if (ioctl(fd, VIDIOC_STREAMOFF, &fmt.type) < 0) {
        perror("Error stopping stream");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    munmap(buf_ptr, buf.length);
    close(fd);

    return 0;
}

