};

struct ssd1306_t *ssd1306_init() {
    int ret;
    struct ssd1306_t *ssd1306 = malloc(sizeof(struct ssd1306_t));
    if (!ssd1306) {
        perror("malloc");
        return NULL;
    }

    const char *dev_name = "/dev/i2c-" I2C_BUS;
    if ((ssd1306->i2c_fd = open(dev_name, O_RDWR)) < 0) {
        perror("open");
        free(ssd1306);
        return NULL;
    }

    if (ioctl(ssd1306->i2c_fd, I2C_SLAVE, SSD1306_ADDR) < 0) {
        perror("ioctl");
        close(ssd1306->i2c_fd);
        free(ssd1306);
        return NULL;
    }

    fcntl(ssd1306->i2c_fd, F_SETFL, O_NONBLOCK);

    ssd1306->i2c_mem = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, ssd1306->i2c_fd, 0);
    if (ssd1306->i2c_mem == MAP_FAILED) {
        perror("mmap");
        close(ssd1306->i2c_fd);
        free(ssd1306);
        return NULL;
    }

    return ssd1306;
}

void ssd1306_clear(struct ssd1306_t *ssd1306) {
    uint8_t buf[2] = {0x00, 0x00};
    write(ssd1306->i2c_fd, buf, 2);
}

void ssd1306_putc(struct ssd1306_t *ssd1306, char c) {
    uint8_t buf[2] = {c >> 4, c & 0x0F};
    write(ssd1306->i2c_fd, buf, 2);
}

void ssd1306_puts(struct ssd1306_t *ssd1306, const char *str) {
    for (size_t i = 0; str[i]; ++i) {
        ssd1306_putc(ssd1306, str[i]);
    }
}

