    int sensor_value = gpiod_get_value_cansleep(gpiod_get_line_byname(NULL, "gpio-controller", "gpioline" SENSOR_GPIO_LINE));

    ssd1306_clear(ssd1306);
    ssd1306_puts(ssd1306, "Sensor Value: ");
