    struct timespec ts = {0, 100 * 1e6};

    while (1) {
        gpiod_line_get_value_cansleep(gpiod_get_line_byname(NULL, "gpio-controller", "gpioline" SENSOR_GPIO_LINE));
        int new_value = gpiod_get_value_cansleep(gpiod_get_line_byname(NULL, "gpio-controller", "gpioline" SENSOR_GPIO_LINE));

        if (new_value != sensor_value) {
            sensor_value = new_value;
            char value_str[3] = {sensor_value + '0', '\0'};

            ssd1306_clear(ssd1306);
            ssd1306_puts(ssd1306, "Sensor Value: ");
