        exit(EXIT_FAILURE);
    }

    trig = gpiod_chip_get_line(chip, "gpio17");
    if (!trig) {
        perror("Failed to get gpio17");
        exit(EXIT_FAILURE);
    }

    echo = gpiod_chip_get_line(chip, "gpio23");
    if (!echo) {
        perror("Failed to get gpio23");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(echo, "default");
    gpiod_line_request_output(trig, "default");

    gpiod_line_set_value(trig, 1);
    usleep(10000);
    gpiod_line_set_value(trig, 0);
}

uint32_t get_time_us() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

