    gpiod_line_set_value(echo, 1);
    uint32_t start = get_time_us();
    gpiod_line_set_value(echo, 0);

    uint32_t end;
    while (gpiod_line_get_value(echo) == 0) {
        end = get_time_us();
        if (end - start > 50000) {
            fprintf(stderr, "Ultrasonic sensor did not respond.\n");
            return -1;
        }
        usleep(1000);
    }

    return (get_time_us() - start) / 2.0 / 1000.0;
}

