    data[0] = (ADS1115_REG_PGA_2_048V << 6) | (ADS1115_REG_MUX_SINGLE_END << 4);
    data[1] = ADS1115_REG_MODE_SINGLE_SHOT_1_SHOT;

    // Initialize GPIO line for interrupt (optional)
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, 17); // GPIO17 (14 in BCM2835)
    if (!line) {
        perror("Failed to get GPIO line");
        exit(1);
    }

    gpio_fd = gpiod_line_request_output(line, "ads1115_int", GPIOD_LINE_ACTIVE_LOW);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO line");
        exit(1);
    }

    gpiod_line_set_value(line, 1); // Set GPIO line high to disable interrupt

    while (1) {
        // Start conversion
        i2c_msg[0].buf[0] = ADS1115_REG_CONVERT;
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
        if (ret < 0) {
            perror("Failed to start conversion");
            exit(1);
        }

        usleep(SAMPLE_INTERVAL);

        // Read conversion result
        i2c_msg[1].buf = data;
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
        if (ret < 0) {
            perror("Failed to read conversion result");
            exit(1);
        }

        printf("ADC reading: %d\n", (data[1] << 8 | data[0]) >> 6);

        // Set GPIO line low to trigger interrupt
        gpiod_line_set_value(line, 0);

        // Wait for interrupt
        usleep(10000); // Wait a bit to allow the interrupt to be triggered
        gpiod_line_get_value(line); // Clear the interrupt
    }

    // Release resources
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(gpio_fd);

    return 0;
}

