#define MPU6050_ADDR 0x68
#define ACC_REG 0x3B
#define ACC_DATA_X_LSB 0x3B
#define ACC_DATA_X_MSB 0x3C
#define ACC_DATA_Y_LSB 0x3D
#define ACC_DATA_Y_MSB 0x3E
#define ACC_DATA_Z_LSB 0x3F
#define ACC_DATA_Z_MSB 0x40

int main() {
    int file;
    int ret;
    uint8_t buf[14];
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int gpio_reset_line = 17;

    // Open I2C bus
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    // Initialize GPIO line for MPU6050 reset
    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(file);
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, gpio_reset_line)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(file);
        return 1;
    }

    // Set GPIO line as output and reset MPU6050
    gpiod_line_set_value(line, 0);
    usleep(100000);
    gpiod_line_set_value(line, 1);
    usleep(100000);

    // Initialize I2C communication with MPU6050
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to talk to MPU6050");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        close(file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        ret = read(file, buf, 14);
        if (ret != 14) {
            perror("Failed to read from MPU6050");
            break;
        }

        // Extract accelerometer data from read buffer
        int16_t acc_x = (buf[ACC_DATA_X_LSB] << 8) | buf[ACC_DATA_X_MSB];
        int16_t acc_y = (buf[ACC_DATA_Y_LSB] << 8) | buf[ACC_DATA_Y_MSB];
        int16_t acc_z = (buf[ACC_DATA_Z_LSB] << 8) | buf[ACC_DATA_Z_MSB];

        // Print accelerometer data
        printf("Accelerometer data: X=%d, Y=%d, Z=%d\n", acc_x, acc_y, acc_z);

        usleep(100000); // Sleep for 0.01 seconds
    }

    // Close I2C file
    close(file);

    // Release GPIO line
    gpiod_line_put(line);
    gpiod_chip_close(chip);

    return 0;
}

