int lcd_init() {
    int fd_lcd = open("/dev/i2c-1", O_RDWR);
    if (fd_lcd < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }

    if (ioctl(fd_lcd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(fd_lcd);
        return -1;
    }

    // Function set
    write(fd_lcd, &LCD_CMD_FUNCTION_SET, 1);
    usleep(4000);

    // Display on/off control
    write(fd_lcd, &LCD_CMD_DISPLAY_ON_OFF | LCD_CMD_DISPLAY_ON, 1);
    usleep(4000);

    // Clear display
    write(fd_lcd, &LCD_CMD_CLEAR, 1);
    usleep(2000);

    // Entry mode set
    write(fd_lcd, &LCD_CMD_ENTRY_MODE_SET | LCD_CMD_ENTRY_LEFT_INCREMENT, 1);
    usleep(4000);

    return fd_lcd;
}

void lcd_putc(int fd_lcd, char c) {
    write(fd_lcd, &LCD_CMD_SET_DDRAM | (c & 0x7F), 1);
    usleep(4000);
    write(fd_lcd, &c, 1);
    usleep(4000);
}

void lcd_puts(int fd_lcd, const char *s) {
    while (*s) {
        lcd_putc(fd_lcd, *s++);
    }
}

