    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("Failed to get ECHO line");
        gpiod_line_put(trig);
        gpiod_chip_put(chip);
        return 1;
    }

    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        perror("Failed to get LED line");
