#define MQTT_TOPIC "ads1115/data"                 // Replace with your MQTT topic

static int i2c_fd;
static int data;

void i2c_init() {
    if ((i2c_fd = wiringPiI2CSetup(SDA_PIN, SCL_PIN)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
}

int read_adc() {
    int adc_value;

    adc_value = wiringPiI2CReadReg16(i2c_fd, (0x48 << 1) | (0x0 << 1));
    adc_value = (adc_value >> (14 - 2)) & 0x0FFF; // 12-bit resolution

    return adc_value;
}

void mqtt_message_handler(struct mqttAsyncClient *client, struct mqttMessage *message) {
    (void)client;
    printf("Published message: QoS %d, retained %d, length %d: %s\n", message->qos, message->retained, message->payloadlen, (char *)message->payload);
}

void mqtt_connect_callback(struct mqttAsyncClient *client, int reason) {
    if (reason == MQTT_CONN_ACCEPT_ACCEPTED) {
        printf("Connected to MQTT broker\n");
    } else {
        printf("Failed to connect to MQTT broker: %s\n", mqtt_connack_string(reason));
    }
}

