    i2c_init();

    mqttAsyncClient client;
    mqttAsyncClient_options opts = MQTTAsync_options_initializer;
    opts.clientId = "ads1115_publisher";
    opts.keepAliveInterval = 20;
    opts.cleansession = 1;

    mqttAsyncClient_create(&client, opts);
    mqttAsyncClient_setCallbacks(client, NULL, mqtt_message_handler, mqtt_connect_callback, NULL);

    int rc = mqttAsyncClient_connect(client, MQTT_BROKER, MQTT_TOPIC, MQTT_QOS_0, MQTT_RETAIN_FALSE);
    if (rc != MQTTASYNC_SUCCESS) {
        printf("Failed to connect to MQTT broker: %s\n", mqtt_connack_string(rc));
        exit(1);
    }

    for (int i = 0; i < 10; ++i) {
        data = read_adc();
        printf("Reading %d: %d\n", i, data);

        mqttAsyncClient_message pubmsg = MQTTAsync_message_initializer;
        pubmsg.qos = MQTT_QOS_0;
