    ret = gpiod_line_request_direction(request[GPIO_5], GPIOD_LINE_REQ_DIRECTION_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO_5 direction");
        gpiod_line_put(request[GPIO_13]);
        gpiod_line_put(request[GPIO_6]);
        gpiod_line_put(request[GPIO_5]);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_direction(request[GPIO_6], GPIOD_LINE_REQ_DIRECTION_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO_6 direction");
        gpiod_line_put(request[GPIO_13]);
        gpiod_line_put(request[GPIO_5]);
        gpiod_line_put(request[GPIO_6]);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_direction(request[GPIO_13], GPIOD_LINE_REQ_DIRECTION_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO_13 direction");
        gpiod_line_put(request[GPIO_6]);
        gpiod_line_put(request[GPIO_5]);
        gpiod_line_put(request[GPIO_13]);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set GPIO_5, GPIO_6, and GPIO_13 to the desired state
    gpiod_line_set_value(request[GPIO_5], 1);
    gpiod_line_set_value(request[GPIO_6], 0);
    gpiod_line_set_value(request[GPIO_13], 1);

    printf("Setting GPIO_5: %d\n", gpiod_line_get_value(request[GPIO_5]));
    printf("Setting GPIO_6: %d\n", gpiod_line_get_value(request[GPIO_6]));
    printf("Setting GPIO_13: %d\n", gpiod_line_get_value(request[GPIO_13]));

