#define GPIO_PINS {2, 3, 18, 23, 24}
#define PWM_FREQUENCY 800
#define DUTY_CYCLE_MIN 0
#define DUTY_CYCLE_MAX 100

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    for (size_t i = 0; i < sizeof(GPIO_PINS) / sizeof(int); ++i) {
        int gpio = GPIO_PINS[i];
        if (gpioInitialisePWM(gpio, PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", gpio);
            return 1;
        }

        for (int duty_cycle = DUTY_CYCLE_MIN; duty_cycle <= DUTY_CYCLE_MAX; ++duty_cycle) {
            double pwm_duty_ns = (double)duty_cycle * 1000000000.0 / 100.0 / PWM_FREQUENCY;
            gpioPWM(gpio, pwm_duty_ns);
            printf("PWM duty cycle on GPIO %d set to %d%%\n", gpio, duty_cycle);
            sleep(1);
        }
    }

    for (size_t i = 0; i < sizeof(GPIO_PINS) / sizeof(int); ++i) {
        int gpio = GPIO_PINS[i];
        gpioTerm(gpio);
    }

    gpioTermAll();

    return 0;
}

#include <stdio.h>
