#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

static int gpio_init(int *gpio_handles, int num_gpios) {
    for (int i = 0; i < num_gpios; ++i) {
        if (gpioInitialise() < 0) {
            perror("Failed to initialise pigpio");
            return -1;
        }
        gpio_handles[i] = gpioOpen(GPIO_##GPIO_##_NUM, GPIODirectionOutput);
        if (gpio_handles[i] < 0) {
            perror("Failed to open GPIO");
            gpioTerm();
            return -1;
        }
    }
    return 0;
}

static void gpio_cleanup(int *gpio_handles, int num_gpios) {
    for (int i = 0; i < num_gpios; ++i) {
        if (gpio_handles[i] >= 0) {
            gpioWrite(gpio_handles[i], 0);
            gpioClose(gpio_handles[i]);
        }
    }
    gpioTerm();
}

int main() {
    int gpio_handles[3];
    int duty_cycles[] = {25, 50, 75};
    int num_gpios = sizeof(duty_cycles);

    if (gpio_init(gpio_handles, num_gpios) != 0) {
        return 1;
    }

    while (1) {
        for (int i = 0; i < num_gpios; ++i) {
            gpioWrite(gpio_handles[i], 1);
            usleep(100000 * duty_cycles[i]);
            gpioWrite(gpio_handles[i], 0);
        }
        usleep(50000);
    }

    gpio_cleanup(gpio_handles, num_gpios);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/ioctl.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>

#define PI_CAMERA_BUS_INFO "picamera"
#define PI_CAMERA_DEVICE_NAME "picamera_csi"

static int camera_fd;
static void *buffer;

int init_camera() {
    camera_fd = v4l2_open(PI_CAMERA_DEVICE_NAME, O_RDWR | O_NONBLOCK, 0, NULL);
    if (camera_fd < 0) {
        perror("Error opening camera device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        return -1;
    }

    if (strncmp(cap.driver, PI_CAMERA_BUS_INFO, strlen(PI_CAMERA_BUS_INFO)) != 0) {
        fprintf(stderr, "Connected device is not the Raspberry Pi camera\n");
        return -1;
    }

    struct v4l2_format fmt;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1280;
    fmt.fmt.pix.height = 720;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting camera format");
        return -1;
    }

    struct v4l2_requestbuffers req;
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting camera buffers");
        return -1;
    }

    buffer = mmap(NULL, req.count * sizeof(struct v4l2_buffer), PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping camera buffers");
        return -1;
    }

    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing camera buffer");
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Error starting camera stream");
        return -1;
    }

    return 0;
}

void release_camera() {
    if (buffer) {
        munmap(buffer, req.count * sizeof(struct v4l2_buffer));
    }

    if (camera_fd >= 0) {
        if (ioctl(camera_fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
            perror("Error stopping camera stream");
        }
        close(camera_fd);
    }
}

int save_image(const char *filename) {
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing camera buffer");
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening output file");
        return -1;
    }

    fwrite(buf.m.data, buf.bytesused, 1, fp);
    fclose(fp);

    if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing camera buffer");
        return -1;
    }

    return 0;
}

int main() {
    if (init_camera() < 0) {
        return 1;
    }

    const char *filename = "image.jpg";
    for (int i = 0; i < 10; ++i) {
        sleep(1);
        if (save_image(filename)) {
            fprintf(stderr, "Error saving image\n");
            break;
        }
        printf("Saved image: %s\n", filename);
    }

    release_camera();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
