#define PI_CAMERA_BUS_INFO "picamera"
#define PI_CAMERA_DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buf_ptr;
    ssize_t bytes_read;
    int i;

    fd = open(PI_CAMERA_DEVICE_NAME, O_RDWR | O_NONBLOCK | O_EXCL);
    if (fd < 0) {
        perror("Error opening camera device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        close(fd);
        return 1;
    }

    if (strcmp(cap.driver, "v4l2-subdev") != 0) {
        fprintf(stderr, "Driver does not support V4L2 subdev API\n");
        close(fd);
        return 1;
    }

    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix_fmt = V4L2_PIX_FMT_JPEG;
    fmt.fmt.width = 1296;
    fmt.fmt.height = 720;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &fmt.type) < 0) {
        perror("Error starting stream");
        close(fd);
        return 1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buf_ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buf_ptr == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    FILE *fp = fopen("image.jpg", "wb");
    if (!fp) {
        perror("Error creating output file");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buf_ptr, 1, buf.bytesused, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error re-queuing buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &fmt.type) < 0) {
        perror("Error stopping stream");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    munmap(buf_ptr, buf.length);
    close(fd);

    return 0;
}

