#define DHT22_GPIO_LINE "gpiochip0/gpio25"

int read_dht22(int gpio_fd, uint8_t *data) {
    const int bit_time_us = 50;
    const int pulse_min_us = 20 * bit_time_us;
    const int pulse_max_us = 80 * bit_time_us;
    const int wait_us = 2457 * bit_time_us;

    gpiod_line_request_lines(gpio_fd, 1, "dht22", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);
    gpiod_line_get_value(gpio_fd, 0) == 0 ? sleep(1) : (void)0;

    gpiod_line_get_value(gpio_fd, 0);
    uint32_t start = gpiod_get_event_time(gpio_fd);

    gpiod_line_set_value(gpio_fd, 1);
    usleep(wait_us);
    gpiod_line_set_value(gpio_fd, 0);

    gpiod_line_get_value(gpio_fd, 0);
    uint32_t stop = gpiod_get_event_time(gpio_fd);

    uint32_t pulse_us = stop - start;
    int i;
    for (i = 0; i < 40; i++) {
        gpiod_line_get_value(gpio_fd, 0);
        uint32_t current_us = gpiod_get_event_time(gpio_fd);
        if (current_us - start >= pulse_min_us && current_us - start <= pulse_max_us) {
            data[i / 8] |= (1 << (i % 8));
        } else if (current_us - start > pulse_max_us) {
            fprintf(stderr, "Invalid DHT22 response\n");
            return -1;
        }
        usleep(bit_time_us * 1000);
    }

    int checksum = data[0] + data[2] + data[4] + data[5];
    if (data[1] != checksum) {
        fprintf(stderr, "Invalid DHT22 checksum\n");
        return -1;
    }

    float temperature = (data[4] << 8 | data[5]) / 10.0;
    float humidity = (data[2] << 8 | data[3]) / 10.0;

    printf("Temperature: %.1f°C\n", temperature);
    printf("Humidity: %.1f%%\n", humidity);

    gpiod_line_release_lines(gpio_fd, 1);
    return 0;
}

int main() {
    int gpio_fd = gpiod_open_name_to_index(DHT22_GPIO_LINE);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        return 1;
    }

    if (read_dht22(gpio_fd, (uint8_t[]) { 0 }) < 0) {
        gpiod_close(gpio_fd);
        return 1;
    }

    gpiod_close(gpio_fd);
    return 0;
}

