#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define PI_CAMERA_BUS_INFO "pi camera"
#define PI_CAMERA_DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    void *buf_ptr;
    ssize_t bytes_read;
    int ret;

    fd = open(PI_CAMERA_DEVICE_NAME, O_RDWR | O_NONBLOCK | O_EXCL);

    if (fd < 0) {
        perror("Error opening camera device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        close(fd);
        return 1;
    }

    if (strncmp(cap.driver, PI_CAMERA_BUS_INFO, strlen(PI_CAMERA_BUS_INFO)) != 0) {
        fprintf(stderr, "Wrong camera driver\n");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1280;
    fmt.fmt.pix.height = 720;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);

    if (ret < 0) {
        perror("Error setting camera format");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &fmt.type);
    if (ret < 0) {
        perror("Error starting camera streaming");
        close(fd);
        return 1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buf_ptr = mmap(NULL, buf.length, PROT_READ, MAP_SHARED, fd, buf.m.offset);
    if (buf_ptr == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("Error queuing buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("Error dequeuing buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    bytes_read = read(fd, buf_ptr, buf.bytesused);
    if (bytes_read != buf.bytesused) {
        perror("Error reading buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    FILE *image_file = fopen("image.jpg", "wb");
    if (!image_file) {
        perror("Error creating image file");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buf_ptr, 1, buf.bytesused, image_file);
    fclose(image_file);

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("Error re-queuing buffer");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    ret = ioctl(fd, VIDIOC_STREAMOFF, &fmt.type);
    if (ret < 0) {
        perror("Error stopping camera streaming");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    munmap(buf_ptr, buf.length);
    close(fd);

    return 0;
}

