        perror("gpiod_chip_get_line_request_byindex");
        gpiod_line_request_put(request_10);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_direction_output(request_10, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("gpiod_line_request_direction_output");
        gpiod_line_request_put(request_11);
        gpiod_line_request_put(request_10);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_direction_output(request_11, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("gpiod_line_request_direction_output");
        gpiod_line_request_put(request_10);
        gpiod_line_request_put(request_11);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_set_value(request_10, 1);
    gpiod_line_set_value(request_11, 1);

    sleep(duration);

    gpiod_line_set_value(request_10, 0);
    gpiod_line_set_value(request_11, 0);

    gpiod_line_request_put(request_10);
    gpiod_line_request_put(request_11);
    gpiod_chip_put(chip);

    return 0;
}

