#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_8 8
#define GPIO_9 9
#define GPIO_11 11
#define GPIO_18 18

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        die("Failed to initialise pigpio library");
    }

    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    int duty_cycle = 50; // Duty cycle in percentage (0-100)

    while (1) {
        gpioWrite(GPIO_8, duty_cycle > 50);
        gpioWrite(GPIO_9, duty_cycle < 50);
        gpioWrite(GPIO_11, duty_cycle % 2 == 0);
        gpioWrite(GPIO_18, duty_cycle % 3 == 0);

        duty_cycle = (duty_cycle + 1) % 101; // Increment duty cycle and wrap around

        usleep(1000000); // Sleep for 1 second
    }

    gpioTerminate(); // Release hardware resources on exit
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <string.h>

#define PI_CAMERA_BUS_INFO "pi camera"
#define PI_CAMERA_DEVICE_NAME "/dev/video0"
#define BUFFER_COUNT 3
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_BGR24

struct buffer {
    void *start;
    size_t length;
};

struct v4l2_buffer {
    struct v4l2_buffer_header header;
    struct buffer buffer;
};

int open_camera() {
    int fd = open(PI_CAMERA_DEVICE_NAME, O_RDWR | O_NONBLOCK | O_EXCL, 0);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }

    if (strncmp(cap.driver, PI_CAMERA_BUS_INFO, strlen(PI_CAMERA_BUS_INFO)) != 0) {
        fprintf(stderr, "Wrong device\n");
        close(fd);
        return -1;
    }

    struct v4l2_cropcap cropcap;
    memset(&cropcap, 0, sizeof(cropcap));
    cropcap.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_CROPCAP, &cropcap) < 0) {
        perror("VIDIOC_CROPCAP");
        close(fd);
        return -1;
    }

    struct v4l2_crop crop;
    crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    crop.c = cropcap.defrect;
    if (ioctl(fd, VIDIOC_S_CROP, &crop) < 0) {
        perror("VIDIOC_S_CROP");
        close(fd);
        return -1;
    }

    struct v4l2_format format;
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = WIDTH;
    format.fmt.pix.height = HEIGHT;
    format.fmt.pix.pixelformat = FORMAT;
    if (ioctl(fd, VIDIOC_S_FMT, &format) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    return fd;
}

int request_buffers(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    return req.count;
}

void *map_buffer(int fd, struct v4l2_buffer *buf) {
    int ret = mmap(NULL, buf->header.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->header.m.offset);
    if (ret == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return buf->buffer.start = (void *)ret;
}

void unmap_buffer(int fd, struct v4l2_buffer *buf) {
    if (munmap(buf->buffer.start, buf->header.length) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

void wait_for_buffer(int fd, struct v4l2_buffer *buf) {
    struct pollfd fds = {fd, POLLOUT, 0};
    poll(&fds, 1, -1);
    if (fds.revents & POLLOUT) {
        if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
            perror("VIDIOC_DQBUF");
            exit(EXIT_FAILURE);
        }
    } else {
        fprintf(stderr, "Buffer not ready\n");
        exit(EXIT_FAILURE);
    }
}

void save_image(const void *data, int width, int height) {
    FILE *fp = fopen("image.bmp", "wb");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // BMP header
    fputc('B', fp);
    fputc('M', fp);
    fput32(14 + 40 + 3 * width * height, fp);
    fput32(0, fp);
    fput32(14 + 40, fp);

    // DIB header
    fput32(40, fp);
    fput32(width, fp);
    fput32(height, fp);
    fput16(1, fp);
    fput16(24, fp);
    fput32(0, fp);
    fput32(0, fp);
    fput32(0, fp);
    fput32(0, fp);

    // RGB data
    fwrite(data, 3, width * height, fp);

    fclose(fp);
}

void close_camera(int fd) {
    struct v4l2_buffer buf;
    while (1) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno != EAGAIN) {
                perror("VIDIOC_DQBUF");
                exit(EXIT_FAILURE);
            }
            break;
        }
        unmap_buffer(fd, &buf);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

int main() {
    int fd = open_camera();
    if (fd < 0) {
        fprintf(stderr, "Failed to open camera\n");
        return -1;
    }

    int buffer_count = request_buffers(fd);
    if (buffer_count < 0) {
        fprintf(stderr, "Failed to request buffers\n");
        close_camera(fd);
        return -1;
    }

    struct v4l2_buffer buffers[buffer_count];
    for (int i = 0; i < buffer_count; ++i) {
        buffers[i].header.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].header.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i].header) < 0) {
            perror("VIDIOC_QUERYBUF");
            close_camera(fd);
            return -1;
        }
        buffers[i].buffer.start = map_buffer(fd, &buffers[i]);
    }

    struct timespec ts = {0, 100 * NANOSLEEP_FACTOR};
    while (1) {
        wait_for_buffer(fd, &buffers[0]);
        save_image(buffers[0].buffer.start, WIDTH, HEIGHT);
        for (int i = 1; i < buffer_count; ++i) {
            wait_for_buffer(fd, &buffers[i]);
            struct v4l2_buffer temp = buffers[0];
            buffers[0] = buffers[i];
            buffers[i] = temp;
        }
        nanosleep(&ts, NULL);
    }

    close_camera(fd);
    return 0;
}

