#include <linux/i2c-dev.h>

#define PCF8574_ADDR 0x27
#define PCF8574_REG_PORTA 0x00

int main() {
    int file;
    int ret;
    char buf[2];
    int i;

    // Open the I2C bus
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Attach the PCF8574 device to the I2C bus
    if (ioctl(file, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to attach to PCF8574");
        close(file);
        exit(1);
    }

    // Read the data from the PCF8574
    ret = i2c_smbus_read_byte_data(file, PCF8574_REG_PORTA);
    if (ret < 0) {
        perror("Failed to read from PCF8574");
        close(file);
        exit(1);
    }

    // Display the read data on the LED display
    printf("Read data: ");
    for (i = 0; i < 8; i++) {
        if (1 & (1 << i) & ret)
            printf("1");
        else
            printf("0");
    }
    printf("\n");

    // Close the I2C device and release the bus
    close(file);

    return 0;
}

