#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_LINE_REQUEST_FLAGS (GPIOLIB_REQUEST_DIR_OUT | GPIOLIB_REQUEST_ACTIVE_LOW)

int main() {
    int ret;
    gpiod_line_request_data lines[1];
    gpiod_line_data_callback callback;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 27);
    if (!line) {
        perror("Failed to get line 27");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_dt(line, GPIO_LINE_REQUEST_FLAGS);
    if (ret < 0) {
        perror("Failed to request line 27");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    lines[0] = (gpiod_line_request_data){
        .line = line,
        .consumer = "gpio_blink",
        .callback = callback,
        .data = NULL,
    };

    callback.callback = [](struct gpiod_line *line, int value, void *data) {
        printf("State: %s\n", value ? "ON" : "OFF");
    };

    ret = gpiod_line_request_multiple(lines, 1);
    if (ret < 0) {
        perror("Failed to request line callback");
        gpiod_line_release(lines[0].line);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set the initial state
    gpiod_line_set_value(line, 1);

    // Run the main loop
    while (1) {
        sleep(1);
        gpiod_line_set_value(line, !gpiod_line_get_value(line));
    }

    // Cleanup resources
    gpiod_line_release(lines[0].line);
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}

#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24
#define PWM_MIN 0
#define PWM_MAX 100
#define PWM_FREQ 800
#define DELAY 10000000 // 0.1 seconds in microseconds

int main() {
    int ret;
    int gpios[3] = {GPIO_18, GPIO_23, GPIO_24};
    int pwm_handles[3];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    for (int i = 0; i < 3; ++i) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for pin %d\n", gpios[i]);
            goto cleanup;
        }

        if (gpioHardwarePWM(gpios[i], PWM_FREQ, PWM_MIN) < 0) {
            fprintf(stderr, "Failed to set PWM for pin %d\n", gpios[i]);
            goto cleanup;
        }

        pwm_handles[i] = gpioGetPWMvalue(gpios[i]);
    }

    while (1) {
        for (int i = 0; i < 3; ++i) {
            pwm_handles[i] = (pwm_handles[i] + 1) % (PWM_MAX + 1);
            gpioPWM(gpios[i], pwm_handles[i]);
        }
        usleep(DELAY);
    }

cleanup:
    for (int i = 0; i < 3; ++i) {
        gpioTermPWM(gpios[i]);
        gpioSetMode(gpios[i], PI_INPUT);
    }
    gpioTerm();
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>

#define TRIG_GPIO 18
#define ECHO_GPIO 17
#define MAX_DISTANCE 250
#define MIN_DISTANCE 2

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int ret;
    unsigned int value;
    struct timespec timeout;
    double duration, distance;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (!trig) {
        perror("Failed to get line for TRIG_GPIO");
        gpiod_chip_close(chip);
        return 1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("Failed to get line for ECHO_GPIO");
        gpiod_line_put_value(trig, 0);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(echo, "ultrasonic_sensor", GPIOD_LINE_REQUEST_DIRECTION_IN) < 0) {
        perror("Failed to request output for ECHO_GPIO");
        gpiod_line_put_value(trig, 0);
        gpiod_line_put_value(echo, 0);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig, "ultrasonic_trigger", GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0) {
        perror("Failed to request output for TRIG_GPIO");
        gpiod_line_put_value(echo, 0);
        gpiod_line_put_value(trig, 0);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_set_value(trig, 1);
    usleep(10000); // Wait for the trigger to propagate
    gpiod_line_set_value(trig, 0);

    timeout.tv_sec = 50000; // 50ms resolution, 50ms * 1000 = 50000us
    timeout.tv_nsec = 0;

    if (gpiod_line_get_value(echo, &value) < 0 || clock_gettime(CLOCK_MONOTONIC, &timeout) <= timeout.tv_sec + timeout.tv_nsec / 1000000000) {
        perror("Failed to read ECHO_GPIO or timeout");
        gpiod_line_put_value(trig, 0);
        gpiod_line_put_value(echo, 0);
        gpiod_chip_close(chip);
        return 1;
    }

    duration = (double)(timeout.tv_sec + timeout.tv_nsec / 1000000000 - gpiod_line_get_event_time(echo)) * 1000000; // Convert to microseconds
    distance = (duration * 0.0343) / 2; // Speed of sound in cm/us

    if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }

    gpiod_line_put_value(trig, 0);
    gpiod_line_put_value(echo, 0);
    gpiod_line_release(echo);
    gpiod_line_release(trig);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define GPIO_LINE_REQUEST_FLAGS (GPIOLIB_REQUEST_DIR_OUT | GPIOLIB_REQUEST_ACTIVE_LOW)

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_data data;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    request = gpiod_chip_get_line_request(chip, 23);
    if (!request) {
        perror("Failed to get line request for GPIO 23");
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable line request for GPIO 23");
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        ret = gpiod_line_get_value(request, &data);
        if (ret < 0) {
            perror("Failed to get line value for GPIO 23");
            break;
        }

        printf("GPIO 23 state: %s\n", data.value ? "ON" : "OFF");

        if (!data.value) {
            ret = gpiod_line_set_value(request, 1);
            if (ret < 0) {
                perror("Failed to set line value for GPIO 23");
                break;
            }
        } else {
            ret = gpiod_line_set_value(request, 0);
            if (ret < 0) {
                perror("Failed to set line value for GPIO 23");
                break;
            }
        }

        sleep(5);
    }

    gpiod_line_set_value(request, 0);
    gpiod_line_request_put(request);
    gpiod_chip_put(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define GPIO_BASE "/dev/gpiochip0"
#define GPIO_NUM_2 2
#define GPIO_NUM_3 3
#define GPIO_NUM_17 17
#define DELAY_MS 5000

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req_gpio[3];
    int ret;

    chip = gpiod_chip_open(GPIO_BASE);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    for (int i = 0; i < 3; ++i) {
        req_gpio[i] = gpiod_chip_get_line(chip, GPIO_NUM_2 + i);
        if (!req_gpio[i]) {
            perror("gpiod_chip_get_line");
            goto cleanup;
        }

        ret = gpiod_line_request_direction(req_gpio[i], GPIOD_OUT_INIT_HIGH);
        if (ret < 0) {
            perror("gpiod_line_request_direction");
            goto cleanup;
        }
    }

    for (int cycle = 1; cycle <= 3; ++cycle) {
        printf("Cycle %d:\n", cycle);
        for (int i = 0; i < 3; ++i) {
            gpiod_line_set_value(req_gpio[i], !!(cycle % (i + 1)));
            usleep(DELAY_MS * 1000);
            int value = gpiod_line_get_value(req_gpio[i]);
            if (value < 0 || value != !!(cycle % (i + 1))) {
                fprintf(stderr, "Failed to read GPIO%d state\n", GPIO_NUM_2 + i);
                goto cleanup;
            }
            printf("GPIO%d: %s\n", GPIO_NUM_2 + i, value ? "ON" : "OFF");
        }
    }

cleanup:
    for (int i = 0; i < 3; ++i) {
        if (req_gpio[i]) {
            gpiod_line_release(req_gpio[i]);
            req_gpio[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    return 0;
}

#include <stdio.h>
