#define GPIO_BASE "/dev/gpiochip0"
#define GPIO_17 (7)
#define GPIO_22 (16)
#define GPIO_27 (27)

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request[3];
    int ret;

    chip = gpiod_chip_open(GPIO_BASE);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    request[GPIO_17] = gpiod_chip_get_line(chip, GPIO_17);
    if (!request[GPIO_17]) {
        perror("gpiod_chip_get_line");
        gpiod_chip_put(chip);
        return 1;
    }

    request[GPIO_22] = gpiod_chip_get_line(chip, GPIO_22);
    if (!request[GPIO_22]) {
        perror("gpiod_chip_get_line");
        gpiod_line_put(request[GPIO_17]);
        gpiod_chip_put(chip);
        return 1;
    }

    request[GPIO_27] = gpiod_chip_get_line(chip, GPIO_27);
    if (!request[GPIO_27]) {
        perror("gpiod_chip_get_line");
        gpiod_line_put(request[GPIO_17]);
        gpiod_line_put(request[GPIO_22]);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_request_direction(request[GPIO_17], GPIOD_IN) < 0) {
        perror("gpiod_line_request_direction");
        gpiod_line_put(request[GPIO_27]);
        gpiod_line_put(request[GPIO_22]);
        gpiod_line_put(request[GPIO_17]);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_request_direction(request[GPIO_22], GPIOD_OUT_HIGH) < 0) {
        perror("gpiod_line_request_direction");
        gpiod_line_put(request[GPIO_27]);
        gpiod_line_put(request[GPIO_22]);
        gpiod_line_put(request[GPIO_17]);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_request_direction(request[GPIO_27], GPIOD_OUT_HIGH) < 0) {
        perror("gpiod_line_request_direction");
        gpiod_line_put(request[GPIO_27]);
        gpiod_line_put(request[GPIO_22]);
        gpiod_line_put(request[GPIO_17]);
        gpiod_chip_put(chip);
        return 1;
    }

    printf("Initial state:\n");
    printf("GPIO17: %s\n", gpiod_line_get_value(request[GPIO_17]) ? "High" : "Low");
    printf("GPIO22: High\n");
    printf("GPIO27: High\n");

    gpiod_line_put(request[GPIO_22], 0);
    sleep(1);
    gpiod_line_put(request[GPIO_22], 1);

    printf("After toggling GPIO22:\n");
    printf("GPIO17: %s\n", gpiod_line_get_value(request[GPIO_17]) ? "High" : "Low");
    printf("GPIO22: High\n");
    printf("GPIO27: High\n");

    gpiod_line_put(request[GPIO_27], 0);
    sleep(1);
    gpiod_line_put(request[GPIO_27], 1);

    printf("After toggling GPIO27:\n");
    printf("GPIO17: %s\n", gpiod_line_get_value(request[GPIO_17]) ? "High" : "Low");
    printf("GPIO22: High\n");
    printf("GPIO27: High\n");

    gpiod_line_put(request[GPIO_17]);
    gpiod_line_put(request[GPIO_27]);
    gpiod_line_put(request[GPIO_22]);
    gpiod_chip_put(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
