#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_BASE "/dev/gpiochip0"
#define GPIO_17 (17 * 32 + 0)
#define GPIO_18 (18 * 32 + 0)
#define GPIO_27 (27 * 32 + 0)

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request[3];
    int ret;

    chip = gpiod_chip_open(GPIO_BASE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < 3; ++i) {
        request[i] = gpiod_chip_get_line_request_byindex(chip, i);
        if (!request[i]) {
            perror("Failed to get line request");
            gpiod_chip_put(chip);
            return 1;
        }
    }

    ret = gpiod_line_request_direction_output(request[0], GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set direction for GPIO 17");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_output(request[1], GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set direction for GPIO 18");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_output(request[2], GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to set direction for GPIO 27");
        goto cleanup;
    }

    gpiod_line_set_value(request[0], 1);
    gpiod_line_set_value(request[1], 0);
    gpiod_line_set_value(request[2], 0);

    printf("Initial state: GPIO17=%d, GPIO18=%d, GPIO27=%d\n",
           gpiod_line_get_value(request[0]) ? 1 : 0,
           gpiod_line_get_value(request[1]) ? 1 : 0,
           gpiod_line_get_value(request[2]) ? 1 : 0);

    // Change the state of GPIO18 and GPIO27
    gpiod_line_set_value(request[1], 1);
    gpiod_line_set_value(request[2], 1);

    printf("After changing state: GPIO17=%d, GPIO18=%d, GPIO27=%d\n",
           gpiod_line_get_value(request[0]) ? 1 : 0,
           gpiod_line_get_value(request[1]) ? 1 : 0,
           gpiod_line_get_value(request[2]) ? 1 : 0);

cleanup:
    for (int i = 0; i < 3; ++i) {
        gpiod_line_release(request[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/sysfs.h>

#define SHT31_ADDR 0x44
#define SHT31_CMD_MEASURE_RH 0x24
#define SHT31_CMD_MEASURE_TEMP 0x2C
#define SHT31_CMD_RESET 0x1E

#define SHT31_CRC_POLYNOMIAL 0x31U

int sht31_read_byte(int file) {
    char data[2];
    if (write(file, &SHT31_CMD_RESET, 1) != 1) {
        perror("Failed to write reset command");
        return -1;
    }

    usleep(400000); // Wait for the sensor to reset

    if (write(file, &SHT31_CMD_MEASURE_RH, 1) != 1) {
        perror("Failed to write measure RH command");
        return -1;
    }

    usleep(10 * 1000000); // Wait for the measurement to complete

    if (read(file, data, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    int crc = data[0] & 0x0F;
    int checksum = 0;
    for (int i = 1; i < 9; ++i) {
        checksum ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (checksum & 1) {
                checksum = (checksum >> 1) ^ SHT31_CRC_POLYNOMIAL;
            } else {
                checksum >>= 1;
            }
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "Invalid checksum\n");
        return -1;
    }

    return data[8] | (data[9] << 8);
}

int main() {
    int file;
    if ((file = open("/dev/i2c-1", O_RDWR) < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(file);
        return 1;
    }

    while (1) {
        int temp_raw = sht31_read_byte(file);
        if (temp_raw < 0) {
            perror("Failed to read temperature");
            break;
        }

        float temp = (float)temp_raw / 16.0;
        printf("Temperature: %.2f°C\n", temp);

        usleep(5 * 1000000); // Wait for 5 seconds
    }

    if (ioctl(file, I2C_SLAVE, 0) < 0) {
        perror("Failed to release bus access");
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_COUNT 10

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int offset,
                                unsigned int count, unsigned int flags,
                                const char *label, gpiod_line_callback callback,
                                void *user_data)
{
    return gpiod_chip_request_lines(chip, offset, count, flags, label, callback,
                                    user_data);
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_data lines[GPIO_COUNT];
    int gpios[GPIO_COUNT] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    for (int i = 0; i < GPIO_COUNT; ++i) {
        lines[i].offset = gpios[i];
        lines[i].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        lines[i].consumer = "gpio_example";
    }

    ret = gpiod_chip_request_lines(chip, 0, GPIO_COUNT, 0, "all", NULL, NULL);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup;
    }

    for (int i = 0; i < GPIO_COUNT; ++i) {
        gpiod_line_get_value(lines[i].line);
        printf("Initial state of GPIO%d: %s\n", gpios[i],
               gpiod_line_get_value(lines[i].line) ? "High" : "Low");
    }

    for (int i = 0; i < GPIO_COUNT; ++i) {
        gpiod_line_set_value(lines[i].line, !gpiod_line_get_value(lines[i].line));
        printf("Setting GPIO%d to %s\n", gpios[i],
               gpiod_line_get_value(lines[i].line) ? "High" : "Low");
        sleep(1);
    }

cleanup:
    for (int i = 0; i < GPIO_COUNT; ++i) {
        gpiod_line_release(lines[i].line);
    }
    gpiod_chip_release(chip);
    return ret < 0 ? 1 : 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

static int gpio_fd[3];

void gpio_setup(void) {
    int i;

    for (i = GPIO_17; i <= GPIO_27; ++i) {
        gpio_fd[i - GPIO_17] = gpiod_open_name("gpiochip0", gpio_get_label(i));
        if (gpio_fd[i - GPIO_17] < 0) {
            perror("Failed to open GPIO");
            exit(EXIT_FAILURE);
        }

        if (gpio_direction_output(gpio_fd[i - GPIO_17], 0) < 0) {
            perror("Failed to set GPIO direction");
            exit(EXIT_FAILURE);
        }
    }
}

void gpio_cleanup(void) {
    int i;

    for (i = GPIO_17; i <= GPIO_27; ++i) {
        if (gpio_fd[i - GPIO_17] >= 0) {
            gpiod_close(gpio_fd[i - GPIO_17]);
        }
    }
}

void gpio_toggle(int gpio) {
    gpiod_write_raw_data(gpio_fd[gpio - GPIO_17], !gpio_get_value(gpio_fd[gpio - GPIO_17]));
}

int main(void) {
    gpio_setup();

    while (1) {
        int i;

        for (i = GPIO_17; i <= GPIO_27; ++i) {
            printf("GPIO%d: %s\n", i, gpio_get_value(gpio_fd[i - GPIO_17] ? "ON" : "OFF");
        }

        usleep(1000000); // Sleep for 1 second

        for (i = GPIO_17; i <= GPIO_27; ++i) {
            gpio_toggle(i);
        }
    }

    gpio_cleanup();
    return EXIT_SUCCESS;
}

