#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define GPIO_BASE "/dev/gpiochip0"
#define GPIO_2 (2)
#define GPIO_17 (17)

int main(void) {
    int gpio_fd, ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request[2];
    unsigned int values[2];

    gpio_fd = open(GPIO_BASE, O_RDWR | O_NONBLOCK);
    if (gpio_fd < 0) {
        perror("Failed to open gpiochip");
        return 1;
    }

    chip = gpiod_chip_open_from_fd(gpio_fd);
    if (!chip) {
        perror("Failed to get gpiochip structure");
        close(gpio_fd);
        return 1;
    }

    request[GPIO_2] = gpiod_chip_get_line(chip, GPIO_2);
    if (!request[GPIO_2]) {
        perror("Failed to get GPIO_2 line request");
        gpiod_chip_put(chip);
        close(gpio_fd);
        return 1;
    }

    request[GPIO_17] = gpiod_chip_get_line(chip, GPIO_17);
    if (!request[GPIO_17]) {
        perror("Failed to get GPIO_17 line request");
        gpiod_line_request_free(request[GPIO_2]);
        gpiod_chip_put(chip);
        close(gpio_fd);
        return 1;
    }

    gpiod_line_request_direction_output(request[GPIO_2], 1);
    gpiod_line_request_direction_output(request[GPIO_17], 1);

    while (1) {
        gpiod_line_get_value(request[GPIO_2], &values[GPIO_2]);
        gpiod_line_get_value(request[GPIO_17], &values[GPIO_17]);

        printf("GPIO_2: %s, GPIO_17: %s\n", values[GPIO_2] ? "ON" : "OFF", values[GPIO_17] ? "ON" : "OFF");

        values[GPIO_2] = !values[GPIO_2];
        usleep(500000); // Sleep for 500ms

        values[GPIO_17] = !values[GPIO_17];
        usleep(1100000); // Sleep for 1.1s (600ms + 500ms)
    }

    // Release resources on exit
    gpiod_line_request_free(request[GPIO_2]);
    gpiod_line_request_free(request[GPIO_17]);
    gpiod_chip_put(chip);
    close(gpio_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17
#define NUM_CYCLES 3

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request[3];
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    for (int i = GPIO_2; i <= GPIO_17; ++i) {
        request[i - GPIO_2] = gpiod_line_request_dup(chip, i);
        if (!request[i - GPIO_2]) {
            perror("Failed to request line");
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < NUM_CYCLES; ++cycle) {
        gpiod_line_set_value(request[GPIO_2], 1);
        gpiod_line_set_value(request[GPIO_3], 1);
        gpiod_line_set_value(request[GPIO_17], 1);
        printf("Cycle %d: All GPIOs are HIGH\n", cycle);
        sleep(1);

        gpiod_line_set_value(request[GPIO_2], 0);
        gpiod_line_set_value(request[GPIO_3], 0);
        gpiod_line_set_value(request[GPIO_17], 0);
        printf("Cycle %d: GPIO2, GPIO3, GPIO17 are LOW\n", cycle);
        sleep(1);
    }

cleanup:
    for (int i = GPIO_2; i <= GPIO_17; ++i) {
        if (request[i - GPIO_2]) {
            gpiod_line_release(request[i - GPIO_2]);
            gpiod_line_request_free(request[i - GPIO_2]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
