#define GPIO_LINE_REQUEST_FLAGS (GPIOLIB_REQUEST_DIR_OUT | GPIOLIB_REQUEST_ACTIVE_LOW)

int main() {
    int ret;
    gpiod_line_request_data lines[1];
    gpiod_line_data_values values[1];
    gpiod_line_handle *gpio_line;

    gpiod_library *lib = gpiod_library_get_by_name("gpiochip0");
    if (!lib) {
        perror("Failed to get gpio library");
        return 1;
    }

    ret = gpiod_chip_for_line_request(lib, 2, GPIO_LINE_REQUEST_FLAGS, &lines[0]);
