#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/v4l2-common.h>
#include <linux/v4l2-mediabus.h>
#include <linux/v4l2-types.h>
#include <linux/v4l2-device.h>
#include <sys/ioctl.h>

#define PI_CAM_BUSINFO "22-1a28"
#define PI_CAM_DEVNAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buf_ptr;
    ssize_t bytes_read;
    int ret;

    fd = open(PI_CAM_DEVNAME, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Error opening camera device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1280;
    fmt.fmt.pix.height = 720;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting video format");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            return 1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &req.type) < 0) {
        perror("Error starting stream");
        close(fd);
        return 1;
    }

    usleep(100000); // Wait for buffer to be filled

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        return 1;
    }

    buf_ptr = mmap(NULL, buf.length, PROT_READ, MAP_SHARED, fd, buf.m.offset);
    if (buf_ptr == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    FILE *image_file = fopen("image.jpg", "wb");
    if (!image_file) {
        perror("Error creating image file");
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    bytes_read = fwrite(buf_ptr, 1, buf.length, image_file);
    if (bytes_read != buf.length) {
        perror("Error writing image file");
        fclose(image_file);
        munmap(buf_ptr, buf.length);
        close(fd);
        return 1;
    }

    fclose(image_file);
    munmap(buf_ptr, buf.length);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error re-queuing buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &req.type) < 0) {
        perror("Error stopping stream");
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

