#define GPIO_LINE_REQUEST_EDGE (GPIOLIB_EDGE_FALLING | GPIOLIB_EDGE_RISING)

int main() {
    int ret;
    int gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_state state;

    gpio_fd = gpiod_chip_open("gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    chip = gpiod_chip_get_by_index(gpio_fd, 0);
    if (!chip) {
        perror("Failed to get gpiochip0");
        close(gpio_fd);
        return 1;
    }

    request = gpiod_line_request_create(chip, "my_request", "my_description", GPIO_LINE_REQUEST_FLAGS);
    if (!request) {
        perror("Failed to create line request");
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    ret = gpiod_line_request_set_active_low(request, 0);
    if (ret < 0) {
        perror("Failed to set active low");
        gpiod_line_request_free(request);
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    ret = gpiod_line_request_set_edge_debounce(request, 10);
    if (ret < 0) {
        perror("Failed to set edge debounce");
        gpiod_line_request_free(request);
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    ret = gpiod_line_request_set_edge_sense(request, GPIO_LINE_REQUEST_EDGE);
    if (ret < 0) {
        perror("Failed to set edge sense");
        gpiod_line_request_free(request);
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable line request");
        gpiod_line_request_free(request);
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    while (1) {
        ret = gpiod_line_get_value(request, &state);
        if (ret < 0) {
            perror("Failed to get line value");
            continue;
        }

        if (state.value != 0 && state.value != 1) {
            fprintf(stderr, "Invalid line value: %d\n", state.value);
            continue;
        }

        printf("Line state: %d\n", state.value);
        sleep(5);
    }

    gpiod_line_request_free(request);
    gpiod_chip_close(gpio_fd);

    return 0;
}

#include <stdio.h>
