#include <linux/i2c-dev.h>
#include <sys/sysstat.h>

#define DS18B20_FILE "/sys/bus/w1/devices/"
#define DS18B20_DIR_PATH DS18B20_FILE "28-*"

int read_temp_raw(int fd) {
    char buf[32];
    ssize_t len = read(fd, buf, sizeof(buf));
    if (len < 0) {
        perror("Error reading from sensor");
        return -1;
    }

    if (strncmp(buf, "t=", 2) != 0) {
        fprintf(stderr, "Invalid response from sensor\n");
        return -1;
    }

    int raw = atoi(&buf[2]);
    return raw;
}

float ds18b20_to_temp(int raw) {
    float temp_c = (raw >> 3) / 16.0;
    temp_c = temp_c * temp_c * temp_c + temp_c * temp_c + temp_c;
    temp_c = temp_c / 127.0;
    return temp_c * 1000;
}

int main() {
    int i, fd, ret;
    char path[128];
    struct dirent *entry;
    dirfd_t dirfd = dirfd(NULL);

    if ((dirfd = scandir(DS18B20_DIR_PATH, &entry, NULL, alphasort)) == -1) {
        perror("Error scanning directory");
        return 1;
    }

    if (dirfd == 0) {
        fprintf(stderr, "No DS18B20 devices found\n");
        return 1;
    }

    for (i = 0; i < dirfd; i++) {
        snprintf(path, sizeof(path), DS18B20_DIR_PATH "/%s/w1_slave", entry[i].d_name);
        if ((fd = open(path, O_RDONLY)) == -1) {
            perror("Error opening sensor file");
            return 1;
        }

        ret = read_temp_raw(fd);
        if (ret == -1) {
            close(fd);
            continue;
        }

        float temp_c = ds18b20_to_temp(ret);
        printf("Temperature: %.3f °C\n", temp_c);

        close(fd);
        if (i == 2) {
            break;
        }

        sleep(5);
    }

    return 0;
}

