int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int ret;
    unsigned int trig_value = GPIOD_VALUE_HIGH;
    unsigned int echo_value = GPIOD_VALUE_LOW;
    unsigned long long start_time, end_time, time_diff;
    double distance;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (!trig) {
        perror("Failed to get line for TRIG_GPIO");
        gpiod_chip_put(chip);
        return 1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("Failed to get line for ECHO_GPIO");
        gpiod_line_put(trig);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_request_output(echo, "ultrasonic_sensor", GPIOD_LINE_REQUEST_DIRECTION_IN);
    gpiod_line_set_value(echo, echo_value);

    gpiod_line_request_output(trig, "ultrasonic_trigger", GPIOD_LINE_REQUEST_DIR_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);

    while (1) {
        gpiod_line_set_value(trig, trig_value);
        usleep(10);
        gpiod_line_set_value(trig, echo_value);

        gpiod_line_get_value(echo, &echo_value);
        start_time = get_monotonic_ns();
        while (echo_value == GPIOD_VALUE_HIGH) {
            usleep(100);
            gpiod_line_get_value(echo, &echo_value);
            if (get_monotonic_ns() - start_time > 500000000) {
                printf("No response from sensor.\n");
                break;
            }
        }

        if (echo_value == GPIOD_VALUE_LOW) {
            gpiod_line_get_value(echo, &echo_value);
            end_time = get_monotonic_ns();
            time_diff = end_time - start_time;
            distance = time_diff * 0.017 / 2;
            printf("Distance: %.2f cm\n", distance);
        }

        usleep(SAMPLE_INTERVAL);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_put(chip);

    return 0;
}

