#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define PWM_FREQ 800
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MIN 0
#define DELAY_MS 100

int main() {
    int ret;
    int gpio_handles[3] = {-1, -1, -1};

    if ((ret = pigpio_init()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(ret));
        return 1;
    }

    for (int gpio = GPIO_4; gpio <= GPIO_18; ++gpio) {
        gpio_handles[gpio - GPIO_4] = gpioInitialise(gpio);
        if (gpio_handles[gpio - GPIO_4] < 0) {
            fprintf(stderr, "Failed to initialize GPIO %d: %s\n", gpio, strerror(gpioInitialise(gpio)));
            ret = 1;
            goto cleanup;
        }
    }

    while (1) {
        for (int gpio = GPIO_4; gpio <= GPIO_18; ++gpio) {
            int duty = (gpio - GPIO_4) * PWM_DUTY_MAX / 3 + PWM_DUTY_MIN;
            ret = gpioHardwarePWM(gpio_handles[gpio - GPIO_4], PWM_FREQ, duty);
            if (ret < 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d: %s\n", gpio, strerror(ret));
                ret = 1;
                goto cleanup;
            }
            printf("PWM state on GPIO %d: %d%%\n", gpio, duty * 100 / PWM_DUTY_MAX);
        }
        usleep(DELAY_MS * 1000);
    }

cleanup:
