#define DHT22_GPIO_LINE "gpiochip0\04"
#define DHT22_GPIO_LINE_OFFSET 4

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int i;
    int fd;
    unsigned char buf[5];

    // Initialize the GPIO line
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get line");
        gpiod_chip_put(chip);
        return 1;
    }

    // Set the line as output
    ret = gpiod_line_request_output(line, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request output");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Open the I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Write the start sequence
    if (write(fd, "1101000", 7) != 7) {
        perror("Failed to write start sequence");
        close(fd);
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set the line as input
    ret = gpiod_line_request_input(line, GPIOD_LINE_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request input");
        close(fd);
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Wait for the sensor to respond
    usleep(20 * 1000);

    // Read the data
    if (read(fd, buf, 5) != 5) {
        perror("Failed to read data");
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_line_put(line);
        close(fd);
        gpiod_chip_put(chip);
        return 1;
    }

    // Check for valid data
    if (buf[0] != 0x42 || buf[1] != 0x13 || buf[2] > 100 || buf[3] > 100) {
        printf("Invalid data\n");
        continue;
    }

    // Calculate and print the temperature and humidity
    float temperature = (buf[2] * 256.0 + buf[3]) / 10.0;
    float humidity = (buf[4] * 256.0 + buf[5]) / 10.0;
    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

    // Reset the line
    gpiod_line_set_value(line, 0);

    // Repeat for 3 cycles
    for (i = 1; i < 4; ++i) {
        usleep(3000000); // Wait for 3 seconds
        if (write(fd, "1101000", 7) != 7) {
            perror("Failed to write start sequence");
            close(fd);
            gpiod_line_set_value(line, 0);
            gpiod_line_put(line);
            gpiod_chip_put(chip);
            return 1;
        }

        usleep(20 * 1000); // Wait for the sensor to respond

        if (read(fd, buf, 5) != 5) {
            perror("Failed to read data");
            gpiod_line_set_value(line, 0);
            gpiod_line_put(line);
            close(fd);
            gpiod_chip_put(chip);
            return 1;
        }

        if (buf[0] != 0x42 || buf[1] != 0x13 || buf[2] > 100 || buf[3] > 100) {
            printf("Invalid data\n");
            continue;
        }

        temperature = (buf[2] * 256.0 + buf[3]) / 10.0;
        humidity = (buf[4] * 256.0 + buf[5]) / 10.0;
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
        gpiod_line_set_value(line, 0);
    }

    // Release the line and close the I2C bus
    gpiod_line_put(line);
    close(fd);

    // Release the GPIO chip
    gpiod_chip_put(chip);

    return 0;
}

