#include <libgpiod.h>

#define GPIO_BASE "/dev/gpiochip"
#define GPIO_CHIP_MAX_LABEL_LEN 32

int main() {
    gpiod_chip *chip;
    gpiod_line_request_lines_data lines_data = {0};
    gpiod_line_request *lines[3] = {NULL};
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_BASE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request lines
    lines_data.labels = calloc(3, GPIO_CHIP_MAX_LABEL_LEN);
    lines_data.lines = lines;
    lines_data.n_lines = 3;
    lines_data.flags = GPIOD_LINE_REQUEST_DIRECTION_OUT;

    for (int i = 0; i < 3; ++i) {
        lines[i] = gpiod_chip_request_line(chip, i, "my_gpio_line%d", &lines_data);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            goto cleanup;
        }
    }

    // Set initial state
    gpiod_line_set_value(lines[0], 1);
    gpiod_line_set_value(lines[1], 0);
    gpiod_line_set_value(lines[2], 1);

    // Main loop
    while (1) {
        printf("Current state: %d, %d, %d\n",
               gpiod_line_get_value(lines[0]) ? 1 : 0,
               gpiod_line_get_value(lines[1]) ? 1 : 0,
               gpiod_line_get_value(lines[2]) ? 1 : 0);

        // Toggle GPIO 18 and GPIO 23
        gpiod_line_set_value(lines[1], !gpiod_line_get_value(lines[1]));
        gpiod_line_set_value(lines[2], !gpiod_line_get_value(lines[2]));

        sleep(1);
    }

cleanup:
    // Release lines
    for (int i = 0; i < 3; ++i) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Free memory
    free(lines_data.labels);

    return 0;
}

