void setup_gpio(int gpio) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio);
        exit(EXIT_FAILURE);
    }

    gpioSetPWMfrequency(gpio, 800); // Set PWM frequency to 800 Hz
}

void cleanup_gpio() {
    gpioTerminate();
}

void toggle_gpio(int gpio) {
    gpioWrite(gpio, !gpioRead(gpio));
}

int main() {
    setup_gpio(GPIO_4);
    setup_gpio(GPIO_17);
    setup_gpio(GPIO_18);
    setup_gpio(GPIO_27);

    int cycles = 0;
    for (int i = 0; i < 5; ++i) {
        printf("Cycle %d:\n", cycles + 1);
        toggle_gpio(GPIO_4);
        usleep(60 * 1000 * 1000); // 60 seconds in microseconds
        toggle_gpio(GPIO_4);
        usleep(60 * 1000 * 1000);

        toggle_gpio(GPIO_17);
        usleep(60 * 1000 * 1000);
        toggle_gpio(GPIO_17);
        usleep(60 * 1000 * 1000);

        toggle_gpio(GPIO_18);
        usleep(60 * 1000 * 1000);
        toggle_GPIO(GPIO_18);
        usleep(60 * 1000 * 1000);

        toggle_gpio(GPIO_27);
        usleep(60 * 1000 * 1000);
        toggle_GPIO(GPIO_27);
        usleep(60 * 1000 * 1000);

        cycles++;
        sleep(1); // Wait 1 second before starting the next cycle
    }

    cleanup_gpio();
    return 0;
}

