#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define NUM_PINS 5

static int gpiod_init(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }
    return 0;
}

static void gpiod_terminate(void) {
    gpioTerminate();
}

static int setup_pwm(int gpio) {
    if (gpioHardwarePWM(gpio, 50, 2000) < 0) {
        perror("Failed to setup PWM on GPIO");
        return -1;
    }
    gpioSetMode(gpio, PI_OUTPUT);
    return 0;
}

static void toggle_pwm(int gpio) {
    gpioWrite(gpio, gpioRead(gpio) ^ 1);
}

int main(void) {
    int pins[NUM_PINS] = {17, 18, 22, 23, 24, 25};
    int i;

    if (gpiod_init() < 0) {
        return 1;
    }

    for (i = 0; i < NUM_PINS; ++i) {
        if (setup_pwm(pins[i]) < 0) {
            gpiod_terminate();
            return 1;
        }
    }

    while (1) {
        for (i = 0; i < NUM_PINS; ++i) {
            toggle_pwm(pins[i]);
            printf("PWM state: ");
            for (int j = 0; j < NUM_PINS; ++j) {
                printf("%s", gpioRead(pins[j] > 0 ? pins[j] : pins[j] - NUM_PINS) == 1 ? "ON" : "OFF");
                if (j < NUM_PINS - 1) {
                    printf(", ");
                }
            }
            printf("\n");
            usleep(20000);
        }
    }

    gpiod_terminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define DHT22_DATA_PIN 4
#define DHT22_CLK_PIN 17
#define DHT22_I2C_ADDR 0x22

#define DHT22_INSTRUCTION_READ 0x2F
#define DHT22_INSTRUCTION_RESTART 0xE0

#define DHT22_ACK 0
#define DHT22_NACK 1

int read_bit(int fd) {
    int bit;
    if (ioctl(fd, I2C_SMBUS_READ_BIT, 0x01) < 0) {
        perror("Failed to read bit");
        return -1;
    }
    bit = (ioctl(fd, I2C_SMBUS_READ_BIT, 0x00) >> 8) & 0x01;
    return bit;
}

void send_bit(int fd, int bit) {
    if (bit) {
        if (ioctl(fd, I2C_SMBUS_WRITE_BYTE_DATA, DHT22_INSTRUCTION_RESTART | 0x80) < 0) {
            perror("Failed to send restart");
            return;
        }
        if (ioctl(fd, I2C_SMBUS_WRITE_BYTE_DATA, 0x27) < 0) {
            perror("Failed to send start condition");
            return;
        }
    }

    if (ioctl(fd, I2C_SMBUS_WRITE_BYTE_DATA, (DHT22_INSTRUCTION_READ << 1) | 0x00) < 0) {
        perror("Failed to send read command");
        return;
    }

    usleep(40);

    if (ioctl(fd, I2C_SMBUS_READ_BYTE_DATA, 0x00) < 0) {
        perror("Failed to read data");
        return;
    }

    usleep(80);

    if (bit) {
        if (ioctl(fd, I2C_SMBUS_WRITE_BYTE_DATA, 0x2F) < 0) {
            perror("Failed to send stop condition");
            return;
        }
    } else {
        if (ioctl(fd, I2C_SMBUS_WRITE_BYTE_DATA, 0x2E) < 0) {
            perror("Failed to send stop condition");
            return;
        }
    }
}

int main() {
    int i2c_fd, gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line_data, *line_clk;
    int ret;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, DHT22_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    gpio_fd = gpiod_open_name_with_flags("gpiochip0", GPIOD_OPEN_FLAG_RAW_GPIO);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(1);
    }

    chip = gpiod_chip_get_by_index(gpio_fd, 0);
    line_data = gpiod_get_line_byname(chip, "gpiochip0\004");
    line_clk = gpiod_get_line_byname(chip, "gpiochip0\017");

    if (!line_data || !line_clk) {
        perror("Failed to get GPIO lines");
        gpiod_close(gpio_fd);
        close(i2c_fd);
