#define SPI_BUS 0
#define SPI_DEVICE 0
#define MAX31855_CS 2
#define MAX31855_MOSI 19
#define MAX31855_MISO 20
#define MAX31855_SCLK 21

int open_spi_device(void) {
    int fd;
    char spi_dev_path[32];
    snprintf(spi_dev_path, sizeof(spi_dev_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    fd = open(spi_dev_path, O_RDWR);
    if (fd < 0) {
        perror("Can't open spi device");
        return -1;
    }

    return fd;
}

void close_spi_device(int fd) {
    close(fd);
}

int write_read_spi(int fd, unsigned char *tx_buf, unsigned char *rx_buf, size_t len) {
    struct spi_ioc_transfer transfers[1];
    transfers[0].tx_buf = (unsigned long)tx_buf;
    transfers[0].rx_buf = (unsigned long)rx_buf;
    transfers[0].len = len;
    transfers[0].speed_hz = 1000000;
    transfers[0].bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Can't write and read from spi device");
        return -1;
    }

    return 0;
}

void gpio_setup(void) {
    int gpio_fd;
    int ret;

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Can't open gpiochip0");
        exit(EXIT_FAILURE);
    }

    ret = gpio_tlmm_config(GPIO_CFG(MAX31855_CS, 0, GPIO_CFGL_OUT_HIGH | GPIO_CFGL_PULL_DOWN, GPIO_CFG_NO_INT), 0);
    if (ret < 0) {
        perror("Failed to configure GPIO pin");
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_value(MAX31855_CS, 1);
    if (ret < 0) {
        perror("Failed to set GPIO pin");
        exit(EXIT_FAILURE);
    }

    ret = gpio_tlmm_config(GPIO_CFG(MAX31855_MOSI, 0, GPIO_CFGL_OUT_HIGH | GPIO_CFGL_PULL_DOWN, GPIO_CFG_NO_INT), 0);
    if (ret < 0) {
        perror("Failed to configure GPIO pin");
        exit(EXIT_FAILURE);
    }

    ret = gpio_tlmm_config(GPIO_CFG(MAX31855_MISO, GPIO_INPUT, GPIO_CFGL_PULL_UP, GPIO_CFG_NO_INT), 0);
    if (ret < 0) {
        perror("Failed to configure GPIO pin");
        exit(EXIT_FAILURE);
    }

    ret = gpio_tlmm_config(GPIO_CFG(MAX31855_SCLK, 0, GPIO_CFGL_OUT_HIGH | GPIO_CFGL_PULL_DOWN, GPIO_CFG_NO_INT), 0);
    if (ret < 0) {
        perror("Failed to configure GPIO pin");
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup(void) {
    close(gpio_fd);
}

int main(void) {
    int spi_fd;
    unsigned char tx_buf[2] = {0};
    unsigned char rx_buf[2] = {0};
    int temperature;
    float celcius;

    gpio_setup();

    spi_fd = open_spi_device();
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    gpio_set_value(MAX31855_CS, 0);
    usleep(10);

    tx_buf[0] = 0x44; // Read thermocouple
    tx_buf[1] = 0x00;

    if (write_read_spi(spi_fd, tx_buf, rx_buf, 2) < 0) {
        perror("Failed to read temperature");
        exit(EXIT_FAILURE);
    }

    gpio_set_value(MAX31855_CS, 1);

    temperature = (rx_buf[0] << 8) | rx_buf[1];
    celcius = (temperature * 333.875 + 500.0) / 10.0;

    printf("Temperature: %.2f°C\n", celcius);

    close_spi_device(spi_fd);
    gpio_cleanup();

    return EXIT_SUCCESS;
}

