#define BMP280_ADDR 0x03
#define BMP280_ID 0x56
#define I2C_SLAVE_FORCE 1

#define OSS 3

static int bmp280_read_reg(int fd, uint8_t reg) {
    char data[2];
    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to acquire bus");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    return data[0] << 8 | data[1];
}

static void bmp280_write_reg(int fd, uint8_t reg, uint16_t value) {
    char data[3];
    data[0] = reg;
    data[1] = value >> 8;
    data[2] = value & 0xFF;

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to acquire bus");
        return;
    }

    if (write(fd, data, 3) != 3) {
        perror("Failed to write data");
    }
}

static uint16_t bmp280_read_uint16(int fd, uint8_t reg) {
    return bmp280_read_reg(fd, reg);
}

static int bmp280_init(int *fd) {
    *fd = open("/dev/i2c-1", O_RDWR);
    if (*fd < 0) {
        perror("Failed to open i2c device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to acquire bus");
        close(*fd);
        return -1;
    }

    uint16_t id = bmp280_read_uint16(fd, 0xD0);
    if (id != BMP280_ID) {
        fprintf(stderr, "Wrong device ID\n");
        close(*fd);
        return -1;
    }

    bmp280_write_reg(*fd, 0xF4, 0x26); // Oversampling settings
    bmp280_write_reg(*fd, 0xF5, 0x34); // Oversampling settings
    bmp280_write_reg(*fd, 0xF6, 0x36); // Oversampling settings
    bmp280_write_reg(*fd, 0xF7, 0x00); // Normal mode

    return 0;
}

static void bmp280_deinit(int fd) {
    close(fd);
}

