    int fd;
    if (bmp280_init(&fd) < 0) {
        return 1;
    }

    for (int i = 0; i < 3; ++i) {
        uint16_t pressure = bmp280_read_uint16(fd, 0xF6);
        uint16_t temp = bmp280_read_uint16(fd, 0xF7);
        printf("Reading %d: Pressure = %d, Temperature = %d\n", i + 1, pressure, temp);
