    msgs[1].buf = (char*)&read_buf[3];

    data.wr_msgs = &msgs[0];
    data.rd_msgs = &msgs[1];
    data.nmsgs = 2;

    for (int i = 0; i < 3; ++i) {
        ret = ioctl(i2c_fd, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read from BME280");
            goto close_i2c;
        }

        if (read_buf[0] != BME280_ID) {
            fprintf(stderr, "Wrong device ID: 0x%02x\n", read_buf[0]);
            goto close_i2c;
        }

        int temperature = ((read_buf[2] << 8) | read_buf[1]) / 16.0;
        int humidity = ((read_buf[4] << 8) | read_buf[5]) / 16.0;
        int pressure = ((read_buf[1] << 24) | (read_buf[2] << 16) | (read_buf[3] << 8) | read_buf[4]) / 100.0;

        printf("Reading %d:\n", i + 1);
        printf("Temperature: %.1f°C\n", temperature);
        printf("Humidity: %.1f%%\n", humidity);
        printf("Pressure: %.1f hPa\n");
        printf("\n");

        sleep(5);
    }

close_i2c:
    if (i2c_fd >= 0) close(i2c_fd);

cleanup_gpio:
    gpiod_line_release_lines(1, SDA_LINE, "bme280_sda");
    gpiod_line_release_lines(1, SCL_LINE, "bme280_scl");

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

