    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line 17");
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DIRECTION_OUT;
