#define VEML7700_ADDR 0x10
#define VEML7700_REG_ID 0x00
#define VEML7700_REG_DATA 0x01

static int i2c_file;
static struct i2c_rdwr_ioctl_data i2c_msg[2];
static uint8_t id_buf[2] = {0};
static uint8_t data_buf[2] = {0};

int init_i2c() {
    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    i2c_msg[0].addr = VEML7700_ADDR;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &id_buf;

    i2c_msg[1].addr = VEML7700_ADDR;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = data_buf;

    return 0;
}

int read_veml7700() {
    if (ioctl(i2c_file, I2C_RDWR, i2c_msg) < 0) {
        perror("Failed to read from VEML7700");
        return -1;
    }

    return data_buf[0];
}

void cleanup() {
    if (i2c_file >= 0) {
        close(i2c_file);
    }
}

int main() {
    int ret, gpio_fd;
    gpiod_line_request_lines(0, "veml7700_reset", GPIOD_LINE_REQUEST_INPUT, NULL);
    gpio_fd = gpiod_open_named_line("veml7700_reset");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        goto cleanup_and_exit;
    }

    gpiod_line_set_value(gpio_fd, 1);
    usleep(100000);
    gpiod_line_set_value(gpio_fd, 0);
    usleep(100000);

    if (init_i2c() < 0) {
        goto cleanup_and_exit;
    }

    i2c_rdwr_ioctl_data_init(i2c_msg, ARRAY_SIZE(i2c_msg));

    while (1) {
        ret = read_veml7700();
        if (ret < 0) {
            perror("Failed to read from VEML7700");
            break;
        }

        printf("Light intensity: %d\n", ret);
        sleep(0.5);
    }

    cleanup_and_exit:
    gpiod_line_release(gpio_fd);
    gpiod_close(gpio_fd);
    cleanup();
    return 0;
}

