#define GPIO_LINE 18

int main() {
    int fd, gpio_fd, ret;
    struct termios options;
    char read_buf[256];
    gpiod_line_request_lines(1, GPIO_LINE, GPIOD_IN, "serial_read");
    gpio_fd = gpiod_get_index_fd(0, GPIO_LINE);
    if (gpio_fd < 0) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open serial port");
        gpiod_line_release_lines(1, GPIO_LINE, "serial_read");
        exit(EXIT_FAILURE);
    }

    tcgetattr(fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &options);

    while (1) {
        gpiod_line_get_value_async(gpio_fd, GPIO_LINE, NULL, 1000);
        ret = read(fd, read_buf, sizeof(read_buf));
        if (ret > 0) {
            printf("Received: %s\n", read_buf);
        } else if (errno != EAGAIN) {
            perror("Failed to read from serial port");
        }
        usleep(100000);
    }

    close(fd);
    gpiod_line_release_lines(1, GPIO_LINE, "serial_read");
    gpiod_release_index_fd(gpio_fd);
    return 0;
}

