#define ECHO_GPIO 17
#define SAMPLE_INTERVAL 500000
#define MAX_DISTANCE 250

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int ret;
    unsigned int trig_value = GPIOD_VALUE_HIGH;
    unsigned int echo_value = GPIOD_VALUE_LOW;
    unsigned int trig_edge = GPIOD_EDGE_FALLING;
    unsigned int echo_edge = GPIOD_EDGE_RISING;
    unsigned int timeout = 100000; // 100ms
    unsigned long long start, end;
    float distance;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIG_GPIO);
    if (!trig) {
        perror("Failed to get line for TRIG_GPIO");
        gpiod_chip_put(chip);
        return 1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo) {
        perror("Failed to get line for ECHO_GPIO");
        gpiod_line_put(trig);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_request_output(trig, trig_value);
    if (ret < 0) {
        perror("Failed to request output for TRIG_GPIO");
        gpiod_line_put(echo);
        gpiod_line_put(trig);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(trig, trig_value);
        usleep(10000); // Delay for 10ms to ensure the signal is stable
        gpiod_line_set_value(trig, GPIOD_VALUE_LOW);

        ret = gpiod_line_get_value_async(echo, &echo_value, timeout);
        if (ret < 0) {
            perror("Failed to get value for ECHO_GPIO");
            continue;
        }

        start = get_monotonic_ns();
        while (gpiod_line_get_value(echo) == echo_value) {
            ret = gpiod_line_get_value_async(echo, &echo_value, timeout);
            if (ret < 0) {
                perror("Failed to get value for ECHO_GPIO");
                break;
            }
        }
        end = get_monotonic_ns();

        if (end - start > timeout) {
            printf("Error: Device did not respond.\n");
            continue;
        }

        distance = (float)(end - start) / 2 * 34300 / 2;
        if (distance > MAX_DISTANCE) {
            printf("Error: Distance out of range.\n");
            continue;
        }

        printf("Distance: %.2f cm\n", distance / 10);
        usleep(SAMPLE_INTERVAL);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_put(chip);

    return 0;
}

