int init_pigpio(int *pi, int *gpio_err) {
    if (gpioInitialise() < 0) {
        *gpio_err = 1;
        return -1;
    }
    *pi = pigpio_start(90, NULL);
    if (*pi == NULL) {
        *gpio_err = 1;
        return -1;
    }
