}

void cleanup_pigpio(int pi, int gpio_err, int *last_error) {
    if (gpioTerminate() < 0) {
        *last_error = gpioLastError(pi);
    }
    pigpio_stop(*pi);
}

int main(int argc, char *argv[]) {
    int pi, gpio_err, last_error;
    if (argc != 1) {
        usage(argv[0]);
        return 1;
    }

    if (init_pigpio(&pi, &gpio_err) < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(gpio_err));
        return gpio_err;
    }

    if (gpioSetMode(GPIO_4, PI_OUTPUT) < 0 || gpioSetMode(GPIO_22, PI_OUTPUT) < 0) {
        last_error = gpioLastError(pi);
        fprintf(stderr, "Failed to set GPIO modes: %s\n", gpioStrError(last_error));
        goto cleanup;
