#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define TCS34725_ADDR 0x29
#define TCS34725_ID 0x44
#define TCS34725_EN 18

int main() {
    int i2c_fd, ret;
    char buf[2];
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    struct i2c_msg msg[2];
    uint16_t id, data[4];
    struct gpiod_line *gpio_en;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize I2C message for reading sensor ID
    msg[0].addr = TCS34725_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = buf;

    msg[1].addr = TCS34725_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 6;
    msg[1].buf = data;

    // Perform I2C read operation
    i2c_msg.length = 2;
    i2c_msg.msgs = msg;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_msg) < 0) {
        perror("Failed to read from TCS34725");
        close(i2c_fd);
        return 1;
    }

    // Check if the device is TCS34725
    id = (buf[0] << 8) | buf[1];
    if (id != TCS34725_ID) {
        printf("Connected device is not TCS34725\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO line for enabling the sensor
    gpio_en = gpiod_get_line(0, TCS34725_EN, "out");
    if (IS_ERR(gpio_en)) {
        perror("Failed to get GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO line high to enable the sensor
    gpiod_set_value_cansleep(gpio_en, 1);

    while (1) {
        // Perform I2C read operation for sensor data
        msg[0].addr = TCS34725_ADDR;
        msg[0].flags = 0;
        msg[0].len = 6;
        msg[0].buf = data;

        i2c_msg.length = 1;
        i2c_msg.msgs = msg;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_msg) < 0) {
            perror("Failed to read from TCS34725");
            break;
        }

        printf("R, G, B, C, H, S: %d, %d, %d, %d, %d, %d\n", data[0], data[1], data[2], data[3], data[4], data[5]);
        sleep(0.5);
    }

    // Set GPIO line low to disable the sensor
    gpiod_set_value_cansleep(gpio_en, 0);

    // Release GPIO line
    gpiod_put_line(gpio_en);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

