    gpioSetPWMfrequency(GPIO_3, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQ);

    while (1) {
        // Set PWM duty cycle for each GPIO pin
        gpioPWM(GPIO_2, PWM_DUTY_CYCLE_MIN);
        gpioPWM(GPIO_3, (PWM_DUTY_CYCLE_MAX + PWM_DUTY_CYCLE_MIN) / 2);
        gpioPWM(GPIO_18, PWM_DUTY_CYCLE_MAX);

        sleep(DELAY_MS / 1000);

        // Swap the duty cycle values for the next iteration
        int temp = PWM_DUTY_CYCLE_MIN;
