static int uart_fd;
static struct termios options;
static gpio_line_data_callback_t gpio_cb;
static gpio_line_data gpio_data;

void gpio_line_callback(struct gpiod_line_data *data, void *user_data) {
    (void)user_data;
    if (data->value == 0) {
        // Device is connected
        gpiod_line_request_deinit(gpio_data.line);
        gpiod_line_free(gpio_data.line);
        gpiod_line_request_destroy(gpio_data.request);
    }
}

int main() {
    int ret;
    int gpio_fd;
    struct gpiod_line_request *request;
    struct gpiod_line *line;

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("Failed to open UART device");
        return 1;
    }

    // Configure the UART settings
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 5;
    tcsetattr(uart_fd, TCSANOW, &options);

    // Request the GPIO line
    gpio_fd = gpiod_open_name_with_label(GPIO_LINE_REQUEST_BASELINE, GPIO_LINE_REQUEST_NAME);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        close(uart_fd);
        return 1;
    }

    request = gpiod_line_request_create(gpio_fd, GPIO_LINE_LINE);
    if (!request) {
        perror("Failed to create GPIO line request");
        gpiod_close(gpio_fd);
        close(uart_fd);
        return 1;
    }

    line = gpiod_line_request_get_line(request);
    gpio_data.line = line;
    gpio_data.request = request;

    gpiod_line_request_set_debounce(request, 10);
    gpiod_line_request_set_direction_input(request);
    gpiod_line_request_set_edge_both_edges(request);
    gpiod_line_request_set_callback(request, gpio_cb, NULL);
    gpiod_line_request_enable(request);

    while (1) {
        char buffer[256];
        ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        }
        usleep(100000);
    }

    // Cleanup on interrupt or exit
    gpiod_line_request_deinit(gpio_data.line);
    gpiod_line_free(gpio_data.line);
    gpiod_line_request_destroy(gpio_data.request);
    gpiod_close(gpio_fd);
    close(uart_fd);

    return 0;
}

