        gpiod_line_request_release(requests[i]);
    }

    for (int i = 0; i < NUM_GPIO; ++i) {
        close(gpio_fd[i]);
        gpiod_chip_put(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define MPU6050_ADDR 0x68
#define ACC_XOUT_H 0x3B
#define ACC_XOUT_L 0x3C
#define ACC_YOUT_H 0x3D
#define ACC_YOUT_L 0x3E
#define ACC_ZOUT_H 0x3F
#define ACC_ZOUT_L 0x40

int main() {
    int file;
    int ret;
    uint8_t buf[14];
    struct i2c_rdwr_ioctl_data i2c_msg[2];

    gpiod_line_request_dt(0, "rpi,gpio-shutdown", GPIOD_LINE_REQUEST_INPUT, "MPU6050 Interrupt");
    gpiod_line_get_value(0, "rpi,gpio-shutdown");

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open i2c bus");
        goto cleanup_gpio;
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access");
        goto close_file;
    }

    i2c_msg[0].addr = MPU6050_ADDR;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (char *)&Acc_Reg;
    i2c_msg[0].buf[0] = 0x3B; // Start register address for accelerometer data

    i2c_msg[1].addr = MPU6050_ADDR;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = 14;
    i2c_msg[1].buf = buf;

    ret = ioctl(file, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to read accelerometer data");
        goto close_file;
    }

    close_file:
    close(file);

    // Print accelerometer data
    printf("Accelerometer Data:\n");
    printf("X: %d.%02d\tY: %d.%02d\tZ: %d.%02d\n",
           buf[ACC_XOUT_H] << 8 | buf[ACC_XOUT_L],
           buf[ACC_XOUT_L] >> 6 & 0x3F,
           buf[ACC_YOUT_H] << 8 | buf[ACC_YOUT_L],
           buf[ACC_YOUT_L] >> 6 & 0x3F,
           buf[ACC_ZOUT_H] << 8 | buf[ACC_ZOUT_L],
           buf[ACC_ZOUT_L] >> 6 & 0x3F);

    // Repeat every 1 second
    usleep(1000000);

cleanup_gpio:
    gpiod_line_release(0, "rpi,gpio-shutdown");
    return 0;
}

