#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define GPIO_LINE_REQUEST_FLAGS (GPIOLIB_REQUEST_DIR_OUT | GPIOLIB_REQUEST_ACTIVE_LOW)
#define GPIO_LINE_REQUEST_EDGE_TYPE GPIOLIB_EDGE_RISING
#define GPIO_LINE_REQUEST_DEBOUNCE_JITTER 0
#define GPIO_LINE_REQUEST_TIMEOUT_NS 1000000000

int main() {
    int fd, ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_data data;

    fd = gpiod_chip_open_byname("gpiochip0");
    if (fd < 0) {
        perror("gpiod_chip_open_byname");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get_by_fd(fd);
    if (!chip) {
        perror("gpiod_chip_get_by_fd");
        close(fd);
        exit(EXIT_FAILURE);
    }

    request = gpiod_chip_request_line(chip, "gpio17", GPIO_LINE_REQUEST_FLAGS);
    if (!request) {
        perror("gpiod_chip_request_line");
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_get_value(request, &data);
    if (ret < 0) {
        perror("gpiod_line_get_value");
        gpiod_line_release(request);
        gpiod_chip_release_request(chip, request);
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    printf("Initial state of GPIO17: %s\n", data.value ? "High" : "Low");

    while (1) {
        ret = gpiod_line_set_value(request, !data.value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            gpiod_line_release(request);
            gpiod_chip_release_request(chip, request);
            gpiod_chip_close(chip);
            close(fd);
            exit(EXIT_FAILURE);
        }

        usleep(600000); // Sleep for 0.6 seconds

        ret = gpiod_line_get_value(request, &data);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            gpiod_line_release(request);
            gpiod_chip_release_request(chip, request);
            gpiod_chip_close(chip);
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    gpiod_line_release(request);
    gpiod_chip_release_request(chip, request);
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}
